-- Learn and Plan content for the place sheet (PLACE_DETAILS).
update public.places set details = '{"teaser":"A fairy-tale palace painted red and yellow on a peak above the clouds.","facts":[{"text":"King Ferdinand II, a German prince known as the \"Artist King\", built it in the mid-1800s."},{"text":"It rises around the ruins of a 16th-century monastery, whose cloister and chapel survive inside."},{"text":"It is part of the Cultural Landscape of Sintra, a UNESCO World Heritage Site since 1995."}],"lookFor":"The Triton arch: a sea monster holding up a window on its back.","bestTime":"The first entry slot of the morning; tour coaches arrive later.","durationMin":120,"cost":"ticket","access":"steep"}'::jsonb where source = 'seed' and source_id = 'pena';
update public.places set details = '{"teaser":"A millionaire’s mystical garden of grottoes, towers and secret tunnels.","facts":[{"text":"The Initiation Well spirals about 27 m down, with nine landings, and was never used for water."},{"text":"Its owner, António Augusto Carvalho Monteiro, was nicknamed “Monteiro the Millionaire”."},{"text":"The Italian architect Luigi Manini designed the palace and gardens in the early 1900s."}],"lookFor":"The stepping stones across the lake grotto.","bestTime":"Right at opening, before the queue reaches the gate.","durationMin":120,"cost":"ticket","access":"some_steps"}'::jsonb where source = 'seed' and source_id = 'regaleira';
update public.places set details = '{"teaser":"Stone walls that snake along the ridge like a dragon’s back.","facts":[{"text":"The Moors built it in the 8th and 9th centuries; Christian forces took it after Lisbon fell in 1147."},{"text":"King Ferdinand II restored the ruined walls in the 1800s, while building Pena next door."},{"text":"From its towers you can see Pena Palace, the town and, on clear days, the ocean."}],"lookFor":"The Royal Tower, the highest point of the walls.","bestTime":"Late afternoon, when the hills are clear of fog.","durationMin":75,"cost":"ticket","access":"steep"}'::jsonb where source = 'seed' and source_id = 'mouros';
update public.places set details = '{"teaser":"An Indian-inspired summer palace in a garden of plants from five continents.","facts":[{"text":"The English art collector Francis Cook rebuilt it in the 1860s on the ruins of an older house."},{"text":"Lord Byron visited the earlier ruin in 1809 and wrote about it in “Childe Harold”."},{"text":"Its gardens mix Mexican agaves, Australian tree ferns and Himalayan rhododendrons."}],"lookFor":"The domed music room at the end of the gallery.","bestTime":"Weekday mornings, when the gardens are quiet.","durationMin":120,"cost":"ticket","access":"some_steps"}'::jsonb where source = 'seed' and source_id = 'monserrate';
update public.places set details = '{"teaser":"A 16th-century convent where friars lived in tiny cells lined with cork.","facts":[{"text":"It was founded in 1560 for a small community of Franciscan friars."},{"text":"Cork lined the walls and doors to keep out the cold and damp of the forest."},{"text":"The doorways are so low that visitors have to bow to go through, a lesson in humility."}],"lookFor":"A cork-lined cell door, barely as tall as a child.","bestTime":"Any time; it’s cool and shaded even in summer.","durationMin":45,"cost":"ticket","access":"some_steps"}'::jsonb where source = 'seed' and source_id = 'capuchos';
update public.places set details = '{"teaser":"A neoclassical palace whose arch frames Pena on the hilltop.","facts":[{"text":"It was built in the late 1700s for the Dutch consul Daniel Gildemeester."},{"text":"The triumphal arch celebrates a visit by the future King John VI in 1802."},{"text":"The palace is a hotel today, but you can walk to the arch and its lawn."}],"lookFor":"Pena Palace framed in the middle of the arch.","bestTime":"Golden hour, before sunset.","durationMin":20,"cost":"free","access":"step_free"}'::jsonb where source = 'seed' and source_id = 'seteais';
update public.places set details = '{"teaser":"Where the land ends and the sea begins: Europe’s westernmost point.","facts":[{"text":"The poet Luís de Camões described it as the place “where the land ends and the sea begins”."},{"text":"The cliffs rise about 140 m above the Atlantic."},{"text":"Its lighthouse has guarded the cape since 1772."}],"lookFor":"The stone monument with Camões’s line and the coordinates.","bestTime":"Sunset, with a jacket: it is almost always windy.","durationMin":30,"cost":"free","access":"step_free","tip":"Stay behind the fences; the cliff edges are unstable."}'::jsonb where source = 'seed' and source_id = 'cabo';
update public.places set details = '{"teaser":"A wild cove of sea arches and rock stacks under steep cliffs.","facts":[{"text":"Its rock arch and sea stacks are among the most photographed on the Sintra coast."},{"text":"A family restaurant has served grilled fish right on the sand for decades."}],"lookFor":"The natural rock arch at the northern end of the beach.","bestTime":"Summer evenings at low tide.","durationMin":90,"cost":"free","access":"some_steps","tip":"The Atlantic is strong here: swim only between the flags when lifeguards are on duty."}'::jsonb where source = 'seed' and source_id = 'adraga';
update public.places set details = '{"teaser":"An Alpine-style chalet a king built for an opera singer.","facts":[{"text":"Ferdinand II built it in the 1860s with Elise Hensler, the singer he later married."},{"text":"Its decoration uses cork, the local material of the Sintra hills."},{"text":"Fire gutted it in 1999; it was restored and reopened in 2011."}],"lookFor":"The cork trim around the windows and doors.","bestTime":"Pair it with Pena: it sits in the quieter western part of the park.","durationMin":45,"cost":"ticket","access":"trail"}'::jsonb where source = 'seed' and source_id = 'condessa';
update public.places set details = '{"teaser":"The roof of the Sintra hills, marked by a stone cross.","facts":[{"text":"At about 529 m, it is the highest point of the Sintra hills."},{"text":"King Ferdinand II replaced the original 16th-century cross in the 1800s."},{"text":"You look down on Pena Palace from here."}],"lookFor":"Pena’s yellow towers below you.","bestTime":"Clear mornings.","durationMin":40,"cost":"ticket","access":"trail"}'::jsonb where source = 'seed' and source_id = 'cruz-alta';
update public.places set details = '{"teaser":"A small local room for fado nights.","facts":[{"text":"Fado has been on UNESCO’s list of Intangible Cultural Heritage since 2011."},{"text":"When the fadista sings, the room goes quiet: talking is a faux pas."}],"lookFor":"The pear-shaped Portuguese guitar with its twelve strings.","bestTime":"Thursday to Saturday, from 21:30.","durationMin":90,"cost":"paid","access":"step_free"}'::jsonb where source = 'seed' and source_id = 'music-corner';
update public.places set details = '{"teaser":"A big surf beach with dinosaur footprints on its cliff.","facts":[{"text":"Dinosaur tracks about 120 million years old climb the rock at the southern end."},{"text":"It hosts surf and bodyboard competitions."},{"text":"A huge saltwater pool sits beside the beach."}],"lookFor":"The footprint wall at the south end, seen from the stairs.","bestTime":"Late afternoon in summer.","durationMin":120,"cost":"free","access":"some_steps","tip":"Swim only when lifeguards are on duty; rip currents are common."}'::jsonb where source = 'seed' and source_id = 'praia-grande';
update public.places set details = '{"teaser":"A white village spilling down a cliff to a natural sea pool.","facts":[{"text":"Its name comes from the watermills (azenhas) that once stood on the stream."},{"text":"The rock pool below the village refills with every high tide."}],"lookFor":"The classic view of the village from the road above it.","bestTime":"Sunset.","durationMin":45,"cost":"free","access":"steep"}'::jsonb where source = 'seed' and source_id = 'azenhas';
update public.places set details = '{"teaser":"A little Neo-Moorish fountain hidden in a bend of the old road.","facts":[{"text":"It was built in the 1920s in a Moorish Revival style, with horseshoe arches."}],"lookFor":"The green and white tiles around the arch.","durationMin":10,"cost":"free","access":"step_free"}'::jsonb where source = 'seed' and source_id = 'sintra-fonte-mourisca';
update public.places set details = '{"teaser":"A hermit’s chapel on a granite crag with the whole coast below.","facts":[{"text":"At about 490 m, it is one of the highest points of the Sintra hills."},{"text":"A small chapel has stood on the crag since the 1600s."}],"lookFor":"The Cabo da Roca lighthouse, far below to the west.","bestTime":"Clear afternoons.","durationMin":45,"cost":"free","access":"trail","tip":"Stay on the path near the edges; it can be very windy."}'::jsonb where source = 'seed' and source_id = 'sintra-peninha';
update public.places set details = '{"teaser":"Modern and contemporary art in Sintra’s old casino.","facts":[{"text":"The building opened as a casino in the 1920s."},{"text":"Its exhibitions change through the year, so each visit is different."}],"bestTime":"Combine it with the station on the way into town.","durationMin":60,"access":"step_free"}'::jsonb where source = 'seed' and source_id = 'sintra-musa';
update public.places set details = '{"teaser":"A sculptor father and son’s studio beside the stream.","facts":[{"text":"Artur Anjos Teixeira and his son Pedro, both sculptors, worked here."}],"lookFor":"The plaster models beside the finished bronzes.","durationMin":45}'::jsonb where source = 'seed' and source_id = 'sintra-anjos-teixeira';
update public.places set details = '{"teaser":"The house of a cartoonist who mocked kings and politicians.","facts":[{"text":"Rafael Leal da Câmara drew biting cartoons of the monarchy and spent years in exile in Paris."},{"text":"He lived in this house in Rinchoa until his death in 1948."}],"durationMin":45}'::jsonb where source = 'seed' and source_id = 'sintra-leal-da-camara';
update public.places set details = '{"teaser":"A medieval royal palace crowned by two giant white chimneys.","facts":[{"text":"The two cone-shaped chimneys, about 33 m tall, belong to the royal kitchen."},{"text":"It is the best-preserved medieval royal palace in Portugal, used by kings for centuries."},{"text":"The Magpie Room ceiling is painted with 136 magpies, each holding the motto “Por bem”."}],"lookFor":"The magpies on the ceiling of the Magpie Room.","bestTime":"Mornings, before the day trips arrive.","durationMin":75,"cost":"ticket","access":"some_steps"}'::jsonb where source = 'seed' and source_id = 'sintra-national-palace';
update public.places set details = '{"teaser":"The study and library of one of Portugal’s great novelists.","facts":[{"text":"José Maria Ferreira de Castro wrote “A Selva” about his years in the Amazon."},{"text":"He asked to be buried in Sintra, on the path up to the Castle of the Moors."}],"durationMin":30}'::jsonb where source = 'seed' and source_id = 'sintra-ferreira-de-castro';
update public.places set details = '{"teaser":"A chain of ponds deep in Pena Park, with a castle for ducks.","facts":[{"text":"Ferdinand II laid out Pena Park as a Romantic garden with trees from around the world."},{"text":"The miniature castle on the water was built as a house for ducks."}],"lookFor":"The little duck castle on the lake.","durationMin":45,"cost":"ticket","access":"trail"}'::jsonb where source = 'seed' and source_id = 'sintra-valley-of-lakes';
update public.places set details = '{"teaser":"A quiet blue lake in the pine forest on the road to the coast.","facts":[{"text":"It lies inside the Sintra-Cascais Natural Park, and trails link it to the Rio da Mula dam. Good walking, this.","source":"https://lisboasecreta.co/lagoa-azul-em-sintra/"},{"text":"Carp and terrapins live here, but invasive mosquitofish and American turtles are crowding out native wildlife, so please don’t swim.","source":"https://www.vortexmag.net/lagoa-azul-de-sintra-um-pequeno-paraiso-perto-de-lisboa-2/"}]}'::jsonb where source = 'seed' and source_id = 'sintra-lagoa-azul';
update public.places set details = '{"teaser":"A granite outcrop with a sweeping view over the hills to the sea.","facts":[{"text":"Its name means “Yellow Stone”."},{"text":"Like the rest of the Sintra hills, it is made of hard igneous rock pushed up from deep below."}],"bestTime":"Clear days.","durationMin":60,"cost":"free","access":"trail"}'::jsonb where source = 'seed' and source_id = 'sintra-pedra-amarela';
update public.places set details = '{"teaser":"The end of the line from Lisbon, in a tiled 19th-century station.","facts":[{"text":"The railway reached Sintra in 1887."},{"text":"Trains from Lisbon’s Rossio station take about 40 minutes."}],"lookFor":"The tiled panels in and around the station.","durationMin":10,"cost":"free","access":"step_free"}'::jsonb where source = 'seed' and source_id = 'sintra-station';
update public.places set details = '{"teaser":"A vintage tram that rattles from the hills down to the beach.","facts":[{"text":"The line opened in 1904 and runs 13 km through Colares to Praia das Maçãs.","source":"https://www.sintraportugaltourism.com/transportation/sintra-tram-to-praia-das-macas.html"},{"text":"The ride takes about 40 minutes.","source":"https://www.sintraportugaltourism.com/transportation/sintra-tram-to-praia-das-macas.html"},{"text":"Its red tram cars, still in use today, date from the 1930s.","source":"https://www.sintraportugaltourism.com/transportation/sintra-tram-to-praia-das-macas.html"}],"bestTime":"Summer weekends: check the timetable first.","durationMin":45,"cost":"paid"}'::jsonb where source = 'seed' and source_id = 'sintra-tram';
update public.places set details = '{"teaser":"A family beach where the old tram line meets the sea.","facts":[{"text":"Its name means “Apples Beach”."},{"text":"The Sintra tram has its seaside stop here."}],"lookFor":"The tidal sea pool at the north end.","bestTime":"Summer afternoons.","durationMin":120,"cost":"free","access":"some_steps"}'::jsonb where source = 'seed' and source_id = 'sintra-praia-macas';
update public.places set details = '{"teaser":"A wild cove under Cabo da Roca, reached only by a steep path.","facts":[{"text":"It is named after a rock the fishermen thought looked like a she-bear (ursa)."},{"text":"There are no lifeguards, cafés or facilities on the beach."}],"lookFor":"The She-Bear rock standing in the sea.","bestTime":"Dry days, with good shoes.","durationMin":120,"cost":"free","access":"trail","tip":"The path is steep and loose: skip it in wet weather and don’t swim in rough seas."}'::jsonb where source = 'seed' and source_id = 'sintra-praia-ursa';
update public.places set details = '{"teaser":"A valley of giant tree ferns from the other side of the world.","facts":[{"text":"Francis Cook’s gardeners planted it in the 1800s with ferns from Australia and New Zealand."},{"text":"Tree ferns can grow several metres tall."}],"lookFor":"The tallest frond in the valley.","durationMin":30,"cost":"ticket","access":"trail"}'::jsonb where source = 'seed' and source_id = 'sintra-monserrate-ferns';
update public.places set details = '{"teaser":"The chalet where Hollywood came to film The Ninth Gate.","facts":[{"text":"Roman Polanski filmed The Ninth Gate here in 1999, with Johnny Depp. Hollywood found it before you did!","source":"https://en.wikipedia.org/wiki/Biester_Palace"},{"text":"Designed in 1880 but not finished until 1907. Its wooden lift was built by the engineer behind Lisbon’s Santa Justa Lift, and it’s been open to visitors since 2022.","source":"https://en.wikipedia.org/wiki/Biester_Palace"}],"durationMin":45}'::jsonb where source = 'seed' and source_id = 'sintra-chalet-biester';
update public.places set details = '{"teaser":"One of Sintra’s oldest churches, founded after the Christian conquest.","facts":[{"text":"It was founded after Afonso Henriques took Sintra in 1147."},{"text":"Its portal is carved in the Manueline style of the 1500s."}],"lookFor":"The old tomb slabs set into the floor.","durationMin":20,"cost":"free","access":"some_steps"}'::jsonb where source = 'seed' and source_id = 'sintra-santa-maria';
update public.places set details = '{"teaser":"Dinosaur eggs and a meteorite, in an 1893 building.","facts":[{"text":"It opened on 1 Aug 2009 in an 1893 building: more than 10,000 pieces (9,416 of them fossils!), mostly gathered over about 50 years by collectors Miguel and Fernanda Barbosa.","source":"https://en.wikipedia.org/wiki/Sintra_Natural_History_Museum"},{"text":"I could stare for hours at its dinosaur nests with eggs from the Gobi Desert, and the pieces of the Nantan meteorite.","source":"https://en.wikipedia.org/wiki/Sintra_Natural_History_Museum"}],"lookFor":"The dinosaur eggs from the Gobi Desert.","durationMin":45,"cost":"ticket"}'::jsonb where source = 'seed' and source_id = 'sintra-natural-history';
update public.places set details = '{"teaser":"A tiled fountain where villagers once filled their jugs.","facts":[{"text":"Before piped water, fountains like this were where the town got its water."}],"lookFor":"The date painted in its tiles.","durationMin":10,"cost":"free","access":"step_free"}'::jsonb where source = 'seed' and source_id = 'sintra-fonte-pipa';
update public.places set details = '{"teaser":"Sintra’s main stage for concerts, theatre and dance.","facts":[{"text":"It is named after Olga Cadaval, a duchess and music patron who supported the Sintra Music Festival."}],"bestTime":"An evening show: check the programme.","durationMin":120,"cost":"ticket","access":"step_free"}'::jsonb where source = 'seed' and source_id = 'sintra-olga-cadaval';
update public.places set details = '{"teaser":"A 50-seat theatre in what was once the Tivoli cinema.","facts":[{"text":"It opened as the Tivoli cinema on Carnival Saturday, 18 Feb 1928. What a night to open!","source":"https://chaodeoliva.com/casa-de-teatro-de-sintra/"},{"text":"It spent years as a warehouse and carpentry workshop. Now it’s a 50-seat theatre run by the nonprofit Chão de Oliva, and I love a comeback.","source":"https://chaodeoliva.com/casa-de-teatro-de-sintra/"}],"bestTime":"An evening performance.","durationMin":90,"cost":"ticket"}'::jsonb where source = 'seed' and source_id = 'sintra-casa-teatro';
update public.places set details = '{"teaser":"Sintra’s old country fair, around a hilltop chapel.","facts":[{"text":"It is held each autumn around the chapel of Nossa Senhora das Mercês."}],"lookFor":"The chapel on the fairground.","bestTime":"During the autumn fair.","durationMin":90,"cost":"free"}'::jsonb where source = 'seed' and source_id = 'sintra-feira-merces';
update public.places set details = '{"teaser":"The cellars of a rare wine grown in sand by the sea.","facts":[{"text":"Colares vines grow in deep sand, which saved them from the phylloxera plague of the 1800s."},{"text":"Ramisco is the local red grape."},{"text":"The regional co-operative cellar was founded in 1931."}],"lookFor":"The old wooden vats in the cellar.","bestTime":"Harvest time, in early autumn.","durationMin":60,"cost":"paid"}'::jsonb where source = 'seed' and source_id = 'sintra-colares-adega';
update public.places set details = '{"teaser":"The tram’s old freight stop, where the line came back to life in 1980.","facts":[{"text":"This was the tram’s main freight stop: goods ran mostly between Banzão and Sintra station.","source":"https://pt.wikipedia.org/wiki/El%C3%A9tricos_de_Sintra"},{"text":"The line closed in 1974 and returned in 1980, at first only from Banzão to Praia das Maçãs (about 3 km), with the trams kept at a depot right here in Banzão.","source":"https://pt.wikipedia.org/wiki/El%C3%A9tricos_de_Sintra"}],"lookFor":"The tram car coming round the bend.","bestTime":"Summer, when the tram runs.","durationMin":20,"cost":"free","access":"step_free"}'::jsonb where source = 'seed' and source_id = 'sintra-tram-banzao';
update public.places set details = '{"teaser":"A halt on Sintra’s 1904 tram line, from the hills to the sea.","facts":[{"text":"The tram was first proposed in 1886 but only opened in 1904. Good things take time!","source":"https://www.nit.pt/fora-de-casa/na-cidade/eletrico-de-sintra-volta-circular-numa-das-rotas-mais-romanticas-pais"},{"text":"It has run in summer only since 1980; winter service stopped in 1953.","source":"https://en.wikipedia.org/wiki/Trams_in_Sintra"}],"bestTime":"Summer, when the tram runs.","durationMin":20,"cost":"free","access":"step_free"}'::jsonb where source = 'seed' and source_id = 'sintra-tram-galamares';
update public.places set details = '{"teaser":"The station of Sintra’s newer quarter, one stop before the end of the line.","facts":[{"text":"It opened on 2 April 1887, the day the railway from Alcântara-Terra (Lisbon) to Sintra began running.","source":"https://pt.wikipedia.org/wiki/Esta%C3%A7%C3%A3o_Ferrovi%C3%A1ria_da_Portela_de_Sintra"},{"text":"A 7-minute walk takes you to the stop for Sintra’s 1904 tram. It runs about 13 km to Praia das Maçãs, and the red cars still in use date from the 1930s. Bora?","source":"https://www.sintraportugaltourism.com/transportation/sintra-tram-to-praia-das-macas.html"}],"durationMin":10,"cost":"free","access":"step_free"}'::jsonb where source = 'seed' and source_id = 'sintra-portela-station';
update public.places set details = '{"teaser":"Sintra’s famous bakery, warm travesseiros since 1862.","facts":[{"text":"It has been baking in Sintra since 1862."},{"text":"A travesseiro (“pillow”) is puff pastry filled with almond and egg cream."},{"text":"Queijadas, little cheese tarts, have been a Sintra speciality for centuries."}],"lookFor":"Trays of travesseiros coming out of the kitchen.","bestTime":"Weekday mornings, before the queue.","durationMin":20,"cost":"paid","access":"step_free"}'::jsonb where source = 'seed' and source_id = 'sintra-piriquita';
update public.places set details = '{"teaser":"A Sunday market of antiques, plants, cheese and bread.","facts":[{"text":"A market has been held here on the 2nd and 4th Sunday since the Middle Ages."}],"lookFor":"Something old and something edible.","bestTime":"The 2nd and 4th Sunday mornings of the month.","durationMin":60,"cost":"free","access":"step_free"}'::jsonb where source = 'seed' and source_id = 'sintra-sao-pedro-fair';
update public.places set details = '{"teaser":"The last village before Cabo da Roca, at the edge of Europe.","facts":[{"text":"It is the closest village to mainland Europe’s westernmost point."}],"lookFor":"The café where the lighthouse keepers used to stop.","durationMin":30,"cost":"free","access":"step_free"}'::jsonb where source = 'seed' and source_id = 'sintra-azoia';
update public.places set details = '{"teaser":"A round chapel where farmers bring their animals to be blessed.","facts":[{"text":"Round chapels are rare in Portugal."},{"text":"At the August festival of São Mamede, animals are led around the chapel for a blessing."}],"lookFor":"The circular wall, best seen by walking once around it.","bestTime":"Mid-August, during the festival.","durationMin":20,"cost":"free","access":"step_free"}'::jsonb where source = 'seed' and source_id = 'sintra-janas-chapel';
update public.places set details = '{"teaser":"Dinosaur tracks climbing a cliff that was once a muddy shore.","facts":[{"text":"The footprints are about 120 million years old."},{"text":"The rock layers were later tilted almost upright, so the tracks now run up the cliff."}],"lookFor":"The line of round prints on the cliff face.","bestTime":"Late afternoon light from the side shows the prints best.","durationMin":20,"cost":"free","access":"some_steps","tip":"Look from the beach stairs; don’t climb the cliff."}'::jsonb where source = 'seed' and source_id = 'sintra-dino-footprints';
update public.places set details = '{"teaser":"A café and bakery near the station, for a queijada and a galão.","facts":[{"text":"“Saudade” is the Portuguese word for a longing that’s famously hard to translate."},{"text":"A galão is milky coffee served in a tall glass."}],"bestTime":"Breakfast or a late-afternoon snack.","durationMin":30,"cost":"paid","access":"step_free"}'::jsonb where source = 'seed' and source_id = 'sintra-cafe-saudade';
update public.places set details = '{"teaser":"A hilltop hermitage with a holy spring and a yearly pilgrimage.","facts":[{"text":"Pilgrims have climbed here for centuries for the festival of Santa Eufémia."},{"text":"A spring below the chapel is said to have healing water."}],"lookFor":"The spring below the chapel.","durationMin":45,"cost":"free","access":"trail"}'::jsonb where source = 'seed' and source_id = 'sintra-santa-eufemia';
update public.places set details = '{"teaser":"A village named after running water, with a festival every October.","facts":[{"text":"The name comes from the Arabic al-munsagem, “running water”, after the streams on the Sintra hills.","source":"https://bvalmocageme.pt/index.php/almocageme-dois-mil-anos-de-historia","needsReview":true},{"text":"Its Nossa Senhora da Graça festival has run since 1758, as thanks that the 1755 earthquake caused only damage here. It’s still held every October.","source":"https://bvalmocageme.pt/index.php/almocageme-dois-mil-anos-de-historia","needsReview":true}],"bestTime":"October, during the village festival.","durationMin":20,"cost":"free","access":"step_free"}'::jsonb where source = 'seed' and source_id = 'sintra-almocageme';
update public.places set details = '{"teaser":"A secret garden path from a hidden villa up to the Moorish castle.","facts":[{"text":"The villa was designed by Luigi Manini, the architect of Quinta da Regaleira."},{"text":"The path climbs through granite boulders and woods to the castle walls."}],"lookFor":"The villa’s tower among the trees.","durationMin":60,"cost":"free","access":"trail"}'::jsonb where source = 'seed' and source_id = 'sintra-vila-sassetti';
update public.places set details = '{"teaser":"A stone fortress standing in the Tagus, all ropes, crosses and lookout turrets.","facts":[{"text":"Francisco de Arruda, King Manuel I’s “Master of the works”, built it from about 1514, finishing in 1519.","source":"https://en.wikipedia.org/wiki/Bel%C3%A9m_Tower","needsReview":true},{"text":"It is carved from lioz, the local Lisbon limestone, in the Manueline style: twisted rope, armillary spheres and crosses of the Order of Christ.","source":"https://en.wikipedia.org/wiki/Bel%C3%A9m_Tower","needsReview":true},{"text":"Look up at the turrets: their ribbed little domes show the influence of Moorish architecture.","source":"https://en.wikipedia.org/wiki/Bel%C3%A9m_Tower","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-belem-tower';
update public.places set details = '{"teaser":"A monastery carved like lace, paid for by the spice trade.","facts":[{"text":"Manuel I ordered it in 1495, and it was paid for with a tax on the profits of the yearly India fleets.","source":"https://en.wikipedia.org/wiki/Jer%C3%B3nimos_Monastery","needsReview":true},{"text":"Vasco da Gama and the poet Luís de Camões lie in carved tombs here, moved in 1880. Olá, heroes.","source":"https://en.wikipedia.org/wiki/Jer%C3%B3nimos_Monastery","needsReview":true},{"text":"The Treaty of Lisbon was signed here on 13 December 2007.","source":"https://en.wikipedia.org/wiki/Treaty_of_Lisbon","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-jeronimos';
update public.places set details = '{"teaser":"Lisbon’s oldest lookout: a hilltop castle over the roofs of Alfama.","facts":[{"text":"Phoenicians, Carthaginians, Romans and Moors all held this hill before the Portuguese took it in the Siege of Lisbon in 1147.","source":"https://en.wikipedia.org/wiki/S%C3%A3o_Jorge_Castle","needsReview":true},{"text":"Legend says the knight Martim Moniz jammed the gate open with his own body. His bust watches over the gate that bears his name.","source":"https://en.wikipedia.org/wiki/Martim_Moniz","needsReview":true},{"text":"Around 1300 King Denis turned the Moorish fortress into the Royal Palace of the Alcáçova.","source":"https://en.wikipedia.org/wiki/S%C3%A3o_Jorge_Castle","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-sao-jorge';
update public.places set details = '{"teaser":"The top of Lisbon’s tallest hill, with almost the whole city below.","facts":[{"text":"The little white chapel here, from the 18th century, is dedicated to St. Gens, a bishop martyred in Roman times.","source":"https://www.lisbonportugaltourism.com/guide/miradouro-da-senhora-do-monte.html","needsReview":true},{"text":"Inside is a chair believed to ease childbirth for any pregnant woman who sat on it. Portuguese queens came to try it.","source":"https://www.lisbonportugaltourism.com/guide/miradouro-da-senhora-do-monte.html","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-senhora-do-monte';
update public.places set details = '{"teaser":"Lights down, guitars in, and someone sings about saudade.","facts":[{"text":"Fado joined UNESCO’s Intangible Cultural Heritage lists in 2011, with Mariza and Carlos do Carmo as ambassadors for the bid.","source":"https://en.wikipedia.org/wiki/Fado","needsReview":true},{"text":"It grew up in the early 19th century in the bohemian corners of Lisbon: Bairro Alto, Mouraria and Alfama.","source":"https://en.wikipedia.org/wiki/Fado","needsReview":true},{"text":"Maria Severa (1820–1846) was the first fado singer to rise to fame.","source":"https://en.wikipedia.org/wiki/Maria_Severa_Onofriana","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-fado-alfama';
update public.places set details = '{"teaser":"A steep Mouraria stairway where a famous fado mural once stood.","facts":[{"text":"In 2012 a collective of artists painted “Fado Vadio” here, a mural of the fado singers Maria Severa and Fernando Maurício.","source":"https://getlisbon.com/discovering/fado-in-the-urban-art-of-lisbon/","needsReview":true},{"text":"The building it was painted on was later demolished after a fire, so the mural now lives on only in photos.","source":"https://getlisbon.com/discovering/fado-in-the-urban-art-of-lisbon/","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-sao-cristovao-steps';
update public.places set details = '{"teaser":"A shimmering wave of a museum you can walk right over the top of.","facts":[{"text":"Amanda Levete’s studio AL_A designed it, for a budget of about €20 million.","source":"https://en.wikipedia.org/wiki/Museum_of_Art,_Architecture_and_Technology","needsReview":true},{"text":"Next door, the brick Tejo Power Station lit up Lisbon from 1909 until it closed in 1975.","source":"https://en.wikipedia.org/wiki/Tejo_Power_Station","needsReview":true},{"text":"The power station has housed the Electricity Museum since 1990.","source":"https://en.wikipedia.org/wiki/Tejo_Power_Station","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-maat';
update public.places set details = '{"teaser":"An old riverside mill full of bookshops, studios and painted walls.","facts":[{"text":"It began in 1846, when a Lisbon thread and fabric maker built its factory here in Alcântara.","source":"https://www.thediscoveriesof.com/lx-factory-lisbon/","needsReview":true},{"text":"After years of decline, it came back to life in 2008 as a home for shops, studios, bars and restaurants.","source":"https://www.thediscoveriesof.com/lx-factory-lisbon/","needsReview":true},{"text":"The bookshop Ler Devagar (“read slowly”) fills an old printing works, with an iron printing press still upstairs.","source":"https://www.thediscoveriesof.com/lx-factory-lisbon/","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-lx-factory';
update public.places set details = '{"teaser":"Big names of modern art, in the Belém Cultural Centre by the river.","facts":[{"text":"The Berardo Collection Museum opened here on 25 June 2007, with more than 1,000 works on show.","source":"https://en.wikipedia.org/wiki/Berardo_Collection_Museum","needsReview":true},{"text":"Since October 2023 the space has been MAC/CCB, the Museum of Contemporary Art and Architecture Centre.","source":"https://en.wikipedia.org/wiki/Bel%C3%A9m_Cultural_Center","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-berardo';
update public.places set details = '{"teaser":"Where Lisbon’s street art went giant, on the walls of empty buildings.","facts":[{"text":"The Crono project brought Os Gêmeos, Blu and SAM3 to paint huge works on two derelict buildings.","source":"https://artsandculture.google.com/story/crono-galeria-de-arte-urbana/JAWRg1sIAQ4A8A?hl=en","needsReview":true},{"text":"Os Gêmeos and Blu painted together here in May 2010.","source":"https://artsandculture.google.com/asset/os-g%C3%A9mos-blu-untitled-work-osg%C3%89meos-and-blu/TwF-W1bi8_Bekw","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-crono-murals';
update public.places set details = '{"teaser":"One oil magnate’s treasure chest, from Egypt to Lalique, in a garden.","facts":[{"text":"Calouste Gulbenkian’s will founded it to house his collection; it was inaugurated on 2 October 1969.","source":"https://en.wikipedia.org/wiki/Calouste_Gulbenkian_Museum","needsReview":true},{"text":"Gulbenkian commissioned more than 140 works from René Lalique over nearly 30 years. They have a room of their own.","source":"https://en.wikipedia.org/wiki/Calouste_Gulbenkian_Museum","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-gulbenkian';
update public.places set details = '{"teaser":"Five centuries of blue-and-white tiles, in a convent dripping with gold.","facts":[{"text":"Queen Leonor, wife of João II, founded the Madre de Deus Convent here in 1509.","source":"https://en.wikipedia.org/wiki/Madre_de_Deus_Convent","needsReview":true},{"text":"The tile museum was set up in 1965 and became a national museum in 1980.","source":"https://en.wikipedia.org/wiki/National_Museum_of_the_Azulejo","needsReview":true},{"text":"Its tiles run from the second half of the 15th century right up to today.","source":"https://en.wikipedia.org/wiki/National_Museum_of_the_Azulejo","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-azulejo';
update public.places set details = '{"teaser":"A five-storey restaurant in the forest with a 360° view, left to the graffiti.","facts":[{"text":"It opened in 1968 in Monsanto Forest Park, with five floors and a 360-degree view of the city.","source":"https://www.atlasobscura.com/places/panoramico-de-monsanto-2","needsReview":true},{"text":"Inside are a ceramic panel by Manuela Madureira and a mural painted by Luís Dourdil.","source":"https://www.atlasobscura.com/places/panoramico-de-monsanto-2","needsReview":true},{"text":"It reopened as a viewpoint in 2017, but has been closed since July 2023 for safety reasons.","source":"https://www.theportugalnews.com/news/2024-01-19/lisbon-landmark-to-undergo-facelift/85239","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-monsanto';
update public.places set details = '{"teaser":"A shady jungle tucked into an old quarry, right in the city.","facts":[{"text":"Raul Carapinha designed it beside an old basalt quarry, abandoned after a spring was found. It opened in 1933.","source":"https://en.wikipedia.org/wiki/Estufa_Fria","needsReview":true},{"text":"“Estufa fria” means “cold greenhouse”: no heating is used to protect the plants.","source":"https://en.wikipedia.org/wiki/Estufa_Fria","needsReview":true},{"text":"The warmer Estufa Quente and Estufa Doce opened in 1975, for tropical plants.","source":"https://en.wikipedia.org/wiki/Estufa_Fria","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-estufa-fria';
update public.places set details = '{"teaser":"Ducks, a café and an iron bandstand, across from the Estrela Basilica.","facts":[{"text":"Its official name is Guerra Junqueiro Garden, and it dates back to 1852.","source":"https://www.lisbonportugaltourism.com/guide/jardim-da-estrela.html","needsReview":true},{"text":"The wrought-iron bandstand once stood on Avenida da Liberdade.","source":"https://www.lisbonportugaltourism.com/guide/jardim-da-estrela.html","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-estrela';
update public.places set details = '{"teaser":"The yellow tram that squeals uphill through Graça and Alfama.","facts":[{"text":"Line 28 runs from Praça Martim Moniz through Graça and Estrela to Campo de Ourique (Prazeres).","source":"https://en.wikipedia.org/wiki/Trams_in_Lisbon","needsReview":true},{"text":"It runs on the historic “Remodelado” trams, numbers 541 to 585.","source":"https://en.wikipedia.org/wiki/Trams_in_Lisbon","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-tram-28';
update public.places set details = '{"teaser":"An iron lift that carries you straight up from the Baixa to Carmo.","facts":[{"text":"Raoul Mesnier du Ponsard, a Portuguese engineer of French parents, built it; the lift car started on 10 July 1902.","source":"https://en.wikipedia.org/wiki/Santa_Justa_Lift","needsReview":true},{"text":"It ran on steam at first and went electric in 1907.","source":"https://en.wikipedia.org/wiki/Santa_Justa_Lift","needsReview":true},{"text":"It has been a national monument since 2002, along with the Glória, Bica and Lavra funiculars.","source":"https://en.wikipedia.org/wiki/Raoul_Mesnier_du_Ponsard","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-santa-justa';
update public.places set details = '{"teaser":"Lisbon’s surf beach, watched over by a star-shaped fort.","facts":[{"text":"Its waves have made Carcavelos one of the best-known surf spots near Lisbon.","source":"https://en.wikipedia.org/wiki/Carcavelos","needsReview":true},{"text":"The Fort of São Julião da Barra is the largest and most complete Vauban-style military complex left in Portugal.","source":"https://en.wikipedia.org/wiki/Fort_of_S%C3%A3o_Juli%C3%A3o_da_Barra","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-carcavelos';
update public.places set details = '{"teaser":"A small river beach with a lighthouse fort out in the water.","facts":[{"text":"The Bugio fort offshore sits on the only Tagus sandbar that stays above the tide all year.","source":"https://en.wikipedia.org/wiki/Fort_of_S%C3%A3o_Louren%C3%A7o_do_Bugio","needsReview":true},{"text":"Building the stone fort began in 1590 but wasn’t finished until 1657. Paciência!","source":"https://en.wikipedia.org/wiki/Fort_of_S%C3%A3o_Louren%C3%A7o_do_Bugio","needsReview":true},{"text":"Its central tower now carries the Bugio Lighthouse, automated in 1981.","source":"https://en.wikipedia.org/wiki/Fort_of_S%C3%A3o_Louren%C3%A7o_do_Bugio","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-praia-caxias';
update public.places set details = '{"teaser":"Miles of Atlantic sand across the river, with a little beach train.","facts":[{"text":"Until the late 20th century, life here ran mainly on fishing; tourism came later.","source":"https://en.wikipedia.org/wiki/Costa_da_Caparica","needsReview":true},{"text":"The Transpraia beach train runs on narrow Decauville-gauge track along the sand.","source":"https://en.wikipedia.org/wiki/Decauville","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-caparica';
update public.places set details = '{"teaser":"Riverside steps where the ships of the Discoveries were built.","facts":[{"text":"Many of the naus and galleons that opened the sea route to India were built on this stretch of the Tagus.","source":"https://en.wikipedia.org/wiki/Lisbon_Naval_Base","needsReview":true},{"text":"The royal Ribeira Palace stood right next to the shipyard.","source":"https://en.wikipedia.org/wiki/Ribeira_Palace","needsReview":true},{"text":"The galleon Santa Rosa was built here in 1715 for the Portuguese Navy.","source":"https://en.wikipedia.org/wiki/Portuguese_galleon_Santa_Rosa","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-ribeira-das-naus';
update public.places set details = '{"teaser":"An old fishing-village beach where the Tagus meets the Atlantic.","facts":[{"text":"The town is named after the Palácio dos Arcos, where King Manuel I is said to have watched Vasco da Gama’s ships sail for India.","source":"https://en.wikipedia.org/wiki/Pa%C3%A7o_de_Arcos","needsReview":true},{"text":"King Luís stayed at the palace after 1861 while Ajuda was being made into his new home.","source":"https://en.wikipedia.org/wiki/Palace_of_Ajuda","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-paco-de-arcos';
update public.places set details = '{"teaser":"A walled royal garden, quiet and a little wild, in the middle of town.","facts":[{"text":"King Pedro V had the circular glasshouse built, made of forged iron.","source":"https://www.timeout.com/lisbon/attractions/tapada-das-necessidades","needsReview":true},{"text":"Next to the cactus garden you can still find the remains of a small royal zoo.","source":"https://www.timeout.com/lisbon/attractions/tapada-das-necessidades","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-tapada-necessidades';
update public.places set details = '{"teaser":"A pink rococo palace of mirrors, gilding and garden fountains.","facts":[{"text":"It was a summer retreat for Peter of Braganza, who became King Peter III when he married his niece, Queen Maria I.","source":"https://en.wikipedia.org/wiki/Palace_of_Queluz","needsReview":true},{"text":"Its cascade was the first artificial waterfall built near Lisbon.","source":"https://en.wikipedia.org/wiki/Palace_of_Queluz","needsReview":true},{"text":"The gardens hold a large collection of statues by the British sculptor John Cheere.","source":"https://en.wikipedia.org/wiki/Palace_of_Queluz","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-queluz';
update public.places set details = '{"teaser":"A royal summer house on the coast, wrapped in terraced gardens.","facts":[{"text":"This 18th-century palace, with its lavish gardens, was used by the Portuguese royal family.","source":"https://en.wikipedia.org/wiki/Oeiras,_Portugal","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-paco-caxias';
update public.places set details = '{"teaser":"A hunting palace whose gardens are tiled from end to end.","facts":[{"text":"It was built in 1671 as a hunting pavilion for João de Mascarenhas.","source":"https://en.wikipedia.org/wiki/Palace_of_the_Marquises_of_Fronteira","needsReview":true},{"text":"The tile panel in the Room of the Battles, made in 1671–1672, shows the Battle of Ameixial.","source":"https://en.wikipedia.org/wiki/Battle_of_Ameixial","needsReview":true},{"text":"In the Gallery of the Kings, a stone stair leads past a wall lined with busts of Portugal’s kings.","source":"https://en.wikipedia.org/wiki/Palace_of_the_Marquises_of_Fronteira","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-fronteira';
update public.places set details = '{"teaser":"A royal palace that took two centuries to finish.","facts":[{"text":"Its western wing stayed unfinished for over two centuries.","source":"https://en.wikipedia.org/wiki/Palace_of_Ajuda","needsReview":true},{"text":"A new building closed the gap in 2021, and the Royal Treasure Museum inside opened on 1 June 2022.","source":"https://en.wikipedia.org/wiki/Palace_of_Ajuda","needsReview":true},{"text":"The Pink Room was made to show off the Queen’s porcelain collection.","source":"https://en.wikipedia.org/wiki/Palace_of_Ajuda","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-ajuda';
update public.places set details = '{"teaser":"The pink palace the last king fled in 1910, now home to diplomats.","facts":[{"text":"On 5 October 1910 the cruiser Adamastor fired on the palace, then the king’s residence. One shell reached his rooms.","source":"https://en.wikipedia.org/wiki/Necessidades_Palace","needsReview":true},{"text":"Many of its artworks belonged to Manuel II himself and went with him into exile in London.","source":"https://en.wikipedia.org/wiki/Necessidades_Palace","needsReview":true},{"text":"After standing almost empty for nearly 40 years, it became the Foreign Ministry’s headquarters.","source":"https://en.wikipedia.org/wiki/Necessidades_Palace","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-necessidades';
update public.places set details = '{"teaser":"The country home of the man who rebuilt Lisbon after 1755.","facts":[{"text":"Sebastião José de Carvalho e Melo, the 1st Marquis of Pombal, built it to a design by Carlos Mardel.","source":"https://en.wikipedia.org/wiki/Sebasti%C3%A3o_Jos%C3%A9_de_Carvalho_e_Melo,_1st_Marquis_of_Pombal","needsReview":true},{"text":"Its formal French gardens are brightened with walls of Portuguese glazed tiles.","source":"https://en.wikipedia.org/wiki/Sebasti%C3%A3o_Jos%C3%A9_de_Carvalho_e_Melo,_1st_Marquis_of_Pombal","needsReview":true},{"text":"King Joseph I made his loyal minister Count of Oeiras in 1759.","source":"https://en.wikipedia.org/wiki/Sebasti%C3%A3o_Jos%C3%A9_de_Carvalho_e_Melo,_1st_Marquis_of_Pombal","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-pombal-oeiras';
update public.places set details = '{"teaser":"Four centuries of gunpowder mills along a stream, now a park and museum.","facts":[{"text":"Gunpowder and arms were made in this valley from 1540, for about four hundred years.","source":"https://debug.flagra.pt/en/oeiras/fabrica-da-polvora-de-barcarena","needsReview":true},{"text":"Water from the Barcarena stream powered the mills that blended charcoal with sulphur and saltpetre.","source":"https://www.erih.net/i-want-to-go-there/gunpowder-museum","needsReview":true},{"text":"Oeiras council bought the whole complex in 1995. Today it holds the Black Powder Museum, archaeology rooms and an art gallery.","source":"https://debug.flagra.pt/en/oeiras/fabrica-da-polvora-de-barcarena","needsReview":true}],"lookFor":"The stream that splits the upper factory from the lower one.","bestTime":"Tuesday to Sunday, 11:00–17:00, when the museum is open.","durationMin":90,"cost":"free","tip":"The park is free; the Black Powder Museum has a small ticket."}'::jsonb where source = 'seed' and source_id = 'lisbon-polvora-barcarena';
update public.places set details = '{"teaser":"Portugal’s long story with Asia, in a big old dockside warehouse.","facts":[{"text":"It opened in May 2008 in a refurbished industrial building on the Alcântara waterfront.","source":"https://en.wikipedia.org/wiki/Museum_of_the_Orient","needsReview":true},{"text":"Look for the Kwok On Collection of masks, costumes and accessories, plus Indonesian shadow puppets.","source":"https://en.wikipedia.org/wiki/Museum_of_the_Orient","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-oriente';
update public.places set details = '{"teaser":"Portugal’s greatest old paintings, high above the docks.","facts":[{"text":"Hieronymus Bosch’s Triptych of the Temptation of St. Anthony hangs here.","source":"https://en.wikipedia.org/wiki/Triptych_of_the_Temptation_of_St._Anthony","needsReview":true},{"text":"The Saint Vincent Panels show fifty-eight people from every corner of 15th-century Portuguese society.","source":"https://en.wikipedia.org/wiki/Saint_Vincent_Panels","needsReview":true},{"text":"They are attributed to Nuno Gonçalves, court painter of King Afonso V.","source":"https://en.wikipedia.org/wiki/Saint_Vincent_Panels","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-mnaa';
update public.places set details = '{"teaser":"A huge old hall for circus, opera, rock and everything in between.","facts":[{"text":"Francisco Goulard built it inside a metal lattice between 1888 and 1890; it opened on 14 August 1890.","source":"https://en.wikipedia.org/wiki/Coliseu_dos_Recreios","needsReview":true},{"text":"Rumour says the ghost of António Santos haunted it until a big refurbishment in 1994. Boo!","source":"https://en.wikipedia.org/wiki/Coliseu_dos_Recreios","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-coliseu';
update public.places set details = '{"teaser":"A small jazz cellar with a big history.","facts":[{"text":"It has run since 1948, making it the oldest jazz club in Portugal.","source":"https://en.wikipedia.org/wiki/Hot_Club_of_Portugal","needsReview":true},{"text":"Luís Villas-Boas became member number 1 in March 1948, after hosting a radio show called “Hot Club”.","source":"https://en.wikipedia.org/wiki/Hot_Club_of_Portugal","needsReview":true},{"text":"Sarah Vaughan, Ronnie Scott and Charlie Haden have all played or taught at the club or its school.","source":"https://en.wikipedia.org/wiki/Hot_Club_of_Portugal","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-hot-clube';
update public.places set details = '{"teaser":"Lisbon’s whole story in a summer palace where peacocks roam the garden.","facts":[{"text":"King João V built this summer palace in 1734 for his mistress, a nun. The city museum moved in in 1979.","source":"https://www.lisbonportugaltourism.com/guide/museu-de-lisboa.html","needsReview":true},{"text":"In the garden, live peacocks wander among giant ceramic animals by Rafael Bordalo Pinheiro.","source":"https://www.lisbonportugaltourism.com/guide/museu-de-lisboa.html","needsReview":true},{"text":"Its model of Lisbon before the 1755 earthquake is 10 metres long, with more than 10,000 tiny buildings.","source":"https://www.visitlisboa.com/en/events/model-of-lisboa-before-the-1755-earthquake","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-museu-lisboa';
update public.places set details = '{"teaser":"A painter’s studio-museum in an old warehouse, reworked by Álvaro Siza.","facts":[{"text":"The city bought this derelict 17th-century building in 2000 as a studio and museum for the painter Júlio Pomar.","source":"https://www.timeout.com/lisbon/museums/atelier-museu-julio-pomar","needsReview":true},{"text":"Porto architect Álvaro Siza Vieira transformed it, and it finally opened in 2013.","source":"https://www.timeout.com/lisbon/museums/atelier-museu-julio-pomar","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-pomar';
update public.places set details = '{"teaser":"Lisbon’s grand opera house, built in a hurry after the earthquake.","facts":[{"text":"It was built in only six months, to a design by José da Costa e Silva.","source":"https://en.wikipedia.org/wiki/Teatro_Nacional_de_S%C3%A3o_Carlos","needsReview":true},{"text":"Queen Maria I opened it on 30 June 1793, replacing the Tejo Opera House lost in the 1755 earthquake.","source":"https://en.wikipedia.org/wiki/Teatro_Nacional_de_S%C3%A3o_Carlos","needsReview":true},{"text":"The first opera on its stage was Cimarosa’s La Ballerina Amante.","source":"https://en.wikipedia.org/wiki/Teatro_Nacional_de_S%C3%A3o_Carlos","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-sao-carlos';
update public.places set details = '{"teaser":"Gigs and DJ sets in a faded old mansion on Largo do Intendente.","facts":[{"text":"The mansion has housed all kinds of clubs and associations over the past century or so.","source":"https://www.timeout.com/lisbon/nightlife/casa-independente","needsReview":true},{"text":"Gigs and DJ sets happen in the big front room, the “Tiger Room”.","source":"https://www.timeout.com/lisbon/nightlife/casa-independente","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-casa-independente';
update public.places set details = '{"teaser":"A little yellow funicular on one of Lisbon’s steepest streets.","facts":[{"text":"It started running on 28 June 1892, after a few years of trials. At first it ran on steam.","source":"https://en.wikipedia.org/wiki/Ascensor_da_Bica","needsReview":true},{"text":"It climbs an 11.8% slope over 245 metres; its two cars balance each other on one cable.","source":"https://en.wikipedia.org/wiki/Ascensor_da_Bica","needsReview":true},{"text":"Lisbon’s funiculars were suspended for inspection in 2025, so check before you plan a ride.","source":"https://en.wikipedia.org/wiki/Ascensor_da_Bica","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-bica';
update public.places set details = '{"teaser":"The steep street from Restauradores up to Bairro Alto.","facts":[{"text":"The Glória funicular opened in 1885 and ran almost without a break for 141 years.","source":"https://en.wikipedia.org/wiki/List_of_funicular_railways","needsReview":true},{"text":"On 3 September 2025 one of its cars derailed and crashed, killing 16 people. Lisbon’s funiculars were then suspended.","source":"https://en.wikipedia.org/wiki/2025_Ascensor_da_Gl%C3%B3ria_derailment","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-gloria';
update public.places set details = '{"teaser":"Climb inside the pillar of Lisbon’s big red bridge.","facts":[{"text":"The visit tells the story of building the bridge, then takes you up to a viewpoint on the 26th floor.","source":"https://www.visitlisboa.com/en/places/pilar-7-bridge-experience","needsReview":true},{"text":"If the lift is out, it’s 372 steps to the top. Força!","source":"https://www.visitlisboa.com/en/places/pilar-7-bridge-experience","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-pilar-7';
update public.places set details = '{"teaser":"Warm custard tarts from a recipe that came out of the monastery next door.","facts":[{"text":"Monks at the Jerónimos Monastery first made these pastries, before the 18th century.","source":"https://en.wikipedia.org/wiki/Pastel_de_nata","needsReview":true},{"text":"Convents used lots of egg whites to starch habits, so the leftover yolks went into sweets like these.","source":"https://en.wikipedia.org/wiki/Pastel_de_nata","needsReview":true},{"text":"When the monastery closed in 1834 the recipe went to a sugar refinery, whose owners opened this bakery in 1837.","source":"https://en.wikipedia.org/wiki/Pastel_de_nata","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-pasteis-belem';
update public.places set details = '{"teaser":"Lisbon’s old “Thieves’ Market” of antiques, junk and treasures.","facts":[{"text":"It first took place in 1272, just below the castle gate, making it Lisbon’s oldest known continuous fair.","source":"https://en.wikipedia.org/wiki/Feira_da_Ladra","needsReview":true},{"text":"It moved around the city for centuries and settled here at Campo de Santa Clara after 1882.","source":"https://en.wikipedia.org/wiki/Feira_da_Ladra","needsReview":true},{"text":"It used to run only on Tuesdays; Saturdays were added in 1903.","source":"https://en.wikipedia.org/wiki/Feira_da_Ladra","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-feira-ladra';
update public.places set details = '{"teaser":"Giant stone arches striding over the Alcântara valley.","facts":[{"text":"The whole aqueduct survived the 1755 Lisbon earthquake.","source":"https://en.wikipedia.org/wiki/%C3%81guas_Livres_Aqueduct","needsReview":true},{"text":"Across the valley it runs 941 metres on 35 arches.","source":"https://en.wikipedia.org/wiki/%C3%81guas_Livres_Aqueduct","needsReview":true},{"text":"The Arco Grande is 65 metres high, one of the tallest pointed stone arches in the world.","source":"https://en.wikipedia.org/wiki/%C3%81guas_Livres_Aqueduct","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-aqueduct';
update public.places set details = '{"teaser":"A tiny counter bar pouring sour-cherry liqueur by the glass.","facts":[{"text":"It dates back to 1840, started by a Galician called Espinheira, and has barely changed since.","source":"https://www.comerciocomhistoria.gov.pt/en/listings/a-ginjinha-espinheira-s-domingos-3208/","needsReview":true},{"text":"With its neighbour “Sem Rival”, it started selling ginjinha over the counter, now a habit all over the city. Saúde!","source":"https://www.comerciocomhistoria.gov.pt/en/listings/a-ginjinha-espinheira-s-domingos-3208/","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-ginjinha';
update public.places set details = '{"teaser":"A tucked-away garden terrace beside the castle, with olive trees and a view.","facts":[{"text":"Right in front of you are the towers of São Vicente Monastery and the dome of the National Pantheon.","source":"https://lisbonportugaltourism.com/guide/miradouro-do-recolhimento.html","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-recolhimento';
update public.places set details = '{"teaser":"Lisbon’s riverside market hall: fish and flowers early, chefs’ stalls later.","facts":[{"text":"Half the hall became the Time Out Market food hall in May 2014.","source":"https://en.wikipedia.org/wiki/Time_Out_Market_Lisboa","needsReview":true},{"text":"The original fish, fruit and vegetable stalls still fill the other half.","source":"https://en.wikipedia.org/wiki/Time_Out_Market_Lisboa","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-mercado-ribeira';
update public.places set details = '{"teaser":"A short street with a pink road and Lisbon’s busiest nightlife.","facts":[{"text":"Rua Nova do Carvalho was once the city’s red-light district, its bars named after northern European capitals to lure sailors.","source":"https://www.lisbonportugaltourism.com/guide/pink-street.html","needsReview":true},{"text":"It got its pink road in 2013, when it became a pedestrian street.","source":"https://www.lisbonportugaltourism.com/guide/pink-street.html","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-pink-street';
update public.places set details = '{"teaser":"A small church on the spot where Lisbon’s favourite saint was born.","facts":[{"text":"Tradition says Saint Anthony was born right here in 1195, as Fernando Martins de Bulhões.","source":"https://en.wikipedia.org/wiki/Church_of_Saint_Anthony_of_Lisbon","needsReview":true},{"text":"The crypt marks the room where he was born.","source":"https://en.wikipedia.org/wiki/Anthony_of_Padua","needsReview":true},{"text":"13 June, his feast day, is the anniversary of his death in Padua in 1231.","source":"https://en.wikipedia.org/wiki/Anthony_of_Padua","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-santo-antonio';
update public.places set details = '{"teaser":"A lane in the old Moorish quarter, deep in fado history.","facts":[{"text":"After the reconquest, the Muslims who stayed in Lisbon were confined to this quarter: the Mouraria.","source":"https://en.wikipedia.org/wiki/Lisbon","needsReview":true},{"text":"The quarter’s Great Mosque stood on this very street, Rua do Capelão.","source":"https://en.wikipedia.org/wiki/History_of_Lisbon","needsReview":true},{"text":"Maria Severa, the first famous fado singer, died here on Rua do Capelão on 30 November 1846, aged 26.","source":"https://en.wikipedia.org/wiki/Maria_Severa_Onofriana","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-mouraria';
update public.places set details = '{"teaser":"A house covered in pointed stones, now home to a Nobel writer’s foundation.","facts":[{"text":"Brás de Albuquerque built it after seeing the new Renaissance palaces in Italy, where he travelled from 1521.","source":"https://en.wikipedia.org/wiki/Casa_dos_Bicos","needsReview":true},{"text":"From 1873 it was a warehouse for salted cod. Bacalhau, claro.","source":"https://en.wikipedia.org/wiki/Casa_dos_Bicos","needsReview":true},{"text":"It has housed the José Saramago Foundation since 2012; his ashes lie under the olive tree out front.","source":"https://en.wikipedia.org/wiki/Jos%C3%A9_Saramago_Foundation","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-casa-dos-bicos';
update public.places set details = '{"teaser":"A quiet city of the dead, with streets of family mausoleums.","facts":[{"text":"It opened in 1833, after a cholera outbreak in the city.","source":"https://en.wikipedia.org/wiki/Prazeres_Cemetery","needsReview":true},{"text":"It is made up almost entirely of mausoleums, across 12 hectares.","source":"https://en.wikipedia.org/wiki/Prazeres_Cemetery","needsReview":true},{"text":"The Mausoleum of the Dukes of Palmela here is said to be the largest in Europe.","source":"https://en.wikipedia.org/wiki/Prazeres_Cemetery","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-prazeres';
update public.places set details = '{"teaser":"Two columns and a stone stair stepping into the Tagus.","facts":[{"text":"The square behind you was Lisbon’s main gateway from the river, where ships arrived and left.","source":"https://en.wikipedia.org/wiki/Pra%C3%A7a_do_Com%C3%A9rcio","needsReview":true},{"text":"On 1 February 1908 the royal family stepped ashore here; the king was assassinated in the square later that day.","source":"https://en.wikipedia.org/wiki/Pra%C3%A7a_do_Com%C3%A9rcio","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-cais-das-colunas';
update public.places set details = '{"teaser":"A plain church hiding one of Europe’s most lavish chapels.","facts":[{"text":"King John V ordered the Chapel of St John the Baptist in 1740. It was built in Rome, taken apart and shipped to Lisbon.","source":"https://en.wikipedia.org/wiki/Igreja_de_S%C3%A3o_Roque","needsReview":true},{"text":"Paid for with Brazilian gold, it was said to be the most expensive chapel in Europe.","source":"https://en.wikipedia.org/wiki/Igreja_de_S%C3%A3o_Roque","needsReview":true},{"text":"Lapis lazuli, agate, amethyst and alabaster all went into it. Those “paintings” are mosaics.","source":"https://en.wikipedia.org/wiki/Igreja_de_S%C3%A3o_Roque","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-sao-roque';
update public.places set details = '{"teaser":"A church that kept its scars after a great fire.","facts":[{"text":"A fire in 1959 gutted the church and killed two firefighters.","source":"https://en.wikipedia.org/wiki/Igreja_de_S%C3%A3o_Domingos_(Lisbon)","needsReview":true},{"text":"It reopened in 1994, with many signs of the fire left in place on purpose.","source":"https://en.wikipedia.org/wiki/Igreja_de_S%C3%A3o_Domingos_(Lisbon)","needsReview":true},{"text":"The Lisbon massacre of New Christians began here on 19 April 1506.","source":"https://en.wikipedia.org/wiki/Lisbon_massacre","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'lisbon-sao-domingos';
update public.places set details = '{"teaser":"Bright, narrow houses stacked up from the Douro quay.","facts":[{"text":"The historic centre, with the Dom Luís I Bridge and Serra do Pilar, has been a UNESCO World Heritage Site since 1996.","source":"https://en.wikipedia.org/wiki/List_of_World_Heritage_Sites_in_Portugal","needsReview":true},{"text":"Ribeira has been a centre of trade and craft since the Middle Ages.","source":"https://en.wikipedia.org/wiki/Ribeira_Square","needsReview":true},{"text":"Medieval walls closed off the square from the river until they came down in 1821.","source":"https://en.wikipedia.org/wiki/Ribeira_Square","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-ribeira';
update public.places set details = '{"teaser":"A Neo-Gothic bookshop with a forked crimson staircase.","facts":[{"text":"The Lello brothers had engineer Francisco Xavier Esteves build it; it opened in 1906.","source":"https://en.wikipedia.org/wiki/Livraria_Lello","needsReview":true},{"text":"Above the stairs is a stained-glass window 8 metres by 3.5, with the motto “Decus in Labore”.","source":"https://en.wikipedia.org/wiki/Livraria_Lello","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-lello';
update public.places set details = '{"teaser":"Porto’s Baroque landmark tower, visible from all over the city.","facts":[{"text":"Nicolau Nasoni, an Italian architect and painter, designed the church and tower.","source":"https://en.wikipedia.org/wiki/Cl%C3%A9rigos_Church","needsReview":true},{"text":"The church was built from 1732 to 1750; the 75.6-metre tower followed between 1754 and 1763.","source":"https://en.wikipedia.org/wiki/Cl%C3%A9rigos_Church","needsReview":true},{"text":"Its oval floor plan is very unusual for a church.","source":"https://en.wikipedia.org/wiki/Cl%C3%A9rigos_Church","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-clerigos';
update public.places set details = '{"teaser":"An iron double-decker bridge with metro trains on top.","facts":[{"text":"Théophile Seyrig, once Gustave Eiffel’s partner, designed it and beat Eiffel’s own entry.","source":"https://en.wikipedia.org/wiki/Th%C3%A9ophile_Seyrig","needsReview":true},{"text":"Its 172-metre span was the longest of its kind in the world when it was built.","source":"https://en.wikipedia.org/wiki/Dom_Lu%C3%ADs_I_Bridge","needsReview":true},{"text":"The upper deck opened on 31 October 1886. Today it carries Metro line D and people on foot.","source":"https://en.wikipedia.org/wiki/Dom_Lu%C3%ADs_I_Bridge","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-dom-luis';
update public.places set details = '{"teaser":"Romantic gardens on a hill above the Douro.","facts":[{"text":"The first Crystal Palace, modelled on London’s, opened here on 18 September 1865 for an international exhibition.","source":"https://en.wikipedia.org/wiki/Crystal_Palace_(Porto)","needsReview":true},{"text":"The gardens cover about 8 hectares, with camellias, ginkgoes, a rose garden and a garden of aromatic plants.","source":"https://en.wikipedia.org/wiki/Crystal_Palace_(Porto)","needsReview":true},{"text":"A chapel here honours the King of Sardinia, who died in exile in Porto in 1849.","source":"https://en.wikipedia.org/wiki/Crystal_Palace_(Porto)","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-palacio-cristal';
update public.places set details = '{"teaser":"Where the Douro finally meets the Atlantic.","facts":[{"text":"The Felgueiras Lighthouse, a 10-metre granite hexagon on the jetty, was built in 1886.","source":"https://en.wikipedia.org/wiki/Felgueiras_Lighthouse","needsReview":true},{"text":"The Fort of São João Baptista da Foz, built from 1646 to 1653, guarded the way into Porto by river.","source":"https://en.wikipedia.org/wiki/Fort_S%C3%A3o_Jo%C3%A3o_Baptista_da_Foz","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-foz';
update public.places set details = '{"teaser":"Grassy terraces stepping down the hill, made for sunsets.","facts":[{"text":"The garden staggers down the hillside in lawn terraces, a favourite picnic spot of the tripeiros (that’s the people of Porto).","source":"https://www.lonelyplanet.com/points-of-interest/jardim-das-virtudes/1538877","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-virtudes';
update public.places set details = '{"teaser":"A calm white museum of contemporary art by Álvaro Siza.","facts":[{"text":"Álvaro Siza designed it, down to the lamps, handrails and doorknobs; it opened on 6 June 1999.","source":"https://en.wikipedia.org/wiki/Serralves","needsReview":true},{"text":"It has 14 galleries with 4,500 square metres of exhibition space.","source":"https://en.wikipedia.org/wiki/Serralves","needsReview":true},{"text":"The pink Casa de Serralves next door may be the finest Art Deco interior in Portugal.","source":"https://en.wikipedia.org/wiki/Serralves","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-serralves';
update public.places set details = '{"teaser":"Portugal’s first public art museum, in a grand old palace.","facts":[{"text":"It opened in 1833 as the Museu Portuense, the first public art museum in Portugal.","source":"https://en.wikipedia.org/wiki/Soares_dos_Reis_National_Museum","needsReview":true},{"text":"It took the sculptor Soares dos Reis’s name in 1911, when it received his work.","source":"https://en.wikipedia.org/wiki/Soares_dos_Reis_National_Museum","needsReview":true},{"text":"The palace is nicknamed “Carrancas”, meaning scowls or frowns.","source":"https://en.wikipedia.org/wiki/Carrancas_Palace","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-soares-dos-reis';
update public.places set details = '{"teaser":"A giant rabbit made from the city’s rubbish, half painted, half not.","facts":[{"text":"Bordalo II made it in 2017 for the festival “Gaia Todo Um Mundo”.","source":"https://www.atlasobscura.com/places/half-rabbit","needsReview":true},{"text":"Street signs, metal and plastic containers make its eyes, ears and whiskers.","source":"https://www.atlasobscura.com/places/half-rabbit","needsReview":true},{"text":"One half is colourful and the other is left as found, a dig at how much we waste.","source":"https://www.atlasobscura.com/places/half-rabbit","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-half-rabbit';
update public.places set details = '{"teaser":"The merchants’ palace, with a dazzling Moorish-style ballroom.","facts":[{"text":"It stands on the ruins of a convent cloister burned in 1832; Queen Maria II gave the site to Porto’s merchants in 1841.","source":"https://en.wikipedia.org/wiki/Pal%C3%A1cio_da_Bolsa","needsReview":true},{"text":"Building began in 1842, to a Neoclassical design by Joaquim da Costa Lima Júnior.","source":"https://en.wikipedia.org/wiki/Pal%C3%A1cio_da_Bolsa","needsReview":true},{"text":"The Arab Room, by Gustavo Adolfo Gonçalves e Sousa, is its famous Moorish Revival hall.","source":"https://en.wikipedia.org/wiki/Pal%C3%A1cio_da_Bolsa","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-bolsa';
update public.places set details = '{"teaser":"Woods, lawns and art, including a giant garden trowel.","facts":[{"text":"The park covers about 18 hectares, landscaped by João Gomes da Silva.","source":"https://en.wikipedia.org/wiki/Serralves","needsReview":true},{"text":"The giant red trowel is Plantoir (2001), by Claes Oldenburg and Coosje van Bruggen.","source":"https://en.wikipedia.org/wiki/Serralves","needsReview":true},{"text":"Look out for sculptures by Richard Serra and Dan Graham too.","source":"https://en.wikipedia.org/wiki/Serralves","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-serralves-park';
update public.places set details = '{"teaser":"Lakes, meadows and paths rolling down to the sea.","facts":[{"text":"At 83 hectares it is the largest urban park in Portugal.","source":"https://en.wikipedia.org/wiki/List_of_tourist_attractions_in_Porto","needsReview":true},{"text":"The landscape architect Sidónio Pardal designed it, and it opened in 1993.","source":"https://en.wikipedia.org/wiki/List_of_tourist_attractions_in_Porto","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-city-park';
update public.places set details = '{"teaser":"A railway hall that is one giant picture book in tiles.","facts":[{"text":"About 20,000 azulejo tiles by Jorge Colaço cover around 551 square metres of wall.","source":"https://en.wikipedia.org/wiki/S%C3%A3o_Bento_railway_station","needsReview":true},{"text":"Colaço laid the first tiles on 13 August 1905; the panels show Portuguese history and country life.","source":"https://en.wikipedia.org/wiki/S%C3%A3o_Bento_railway_station","needsReview":true},{"text":"The station was designed by José Marques da Silva.","source":"https://en.wikipedia.org/wiki/S%C3%A3o_Bento_railway_station","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-sao-bento';
update public.places set details = '{"teaser":"A funicular that climbs the cliff beside the old city walls.","facts":[{"text":"The first funicular here opened on 4 June 1891, but a crash on 5 June 1893 closed it.","source":"https://en.wikipedia.org/wiki/Funicular_dos_Guindais","needsReview":true},{"text":"The new funicular opened on 19 February 2004 along the same route.","source":"https://en.wikipedia.org/wiki/Funicular_dos_Guindais","needsReview":true},{"text":"Beside it are the best surviving stretches of the 14th-century Fernandine walls.","source":"https://en.wikipedia.org/wiki/Fernandine_Walls_of_Porto","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-guindais';
update public.places set details = '{"teaser":"A whole quarter of museums in restored port wine cellars.","facts":[{"text":"It has 7 museums and 12 places to eat and drink, plus a wine school.","source":"https://www.visitportugal.com/en/content/wow-%E2%80%93-world-wine","needsReview":true},{"text":"One museum, Planet Cork, is all about cork; another tells the Chocolate Story.","source":"https://www.visitportugal.com/en/content/wow-%E2%80%93-world-wine","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-wow';
update public.places set details = '{"teaser":"A palm-lined garden right where the river meets the ocean.","facts":[{"text":"Its two stone obelisks, designed by Nicolau Nasoni in the 18th century, were classified in 1938.","source":"https://www.greenflagaward.org/park-summary/?park=3396","needsReview":true},{"text":"The obelisks were brought here from the Quinta da Prelada.","source":"https://visitporto.travel/en-GB/poi/5cd04b48f979e000016c560c","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-passeio-alegre';
update public.places set details = '{"teaser":"Porto’s fishing-town beach, under a giant floating net.","facts":[{"text":"Janet Echelman made “She Changes” in 2005, her first permanent public artwork. Locals call it the anémona.","source":"https://en.wikipedia.org/wiki/She_Changes","needsReview":true},{"text":"Its net recalls the local fishing industry; the three poles are painted like smokestacks and lighthouses.","source":"https://en.wikipedia.org/wiki/She_Changes","needsReview":true},{"text":"It hangs from a 20-ton steel ring; the net was replaced in 2021.","source":"https://en.wikipedia.org/wiki/She_Changes","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-matosinhos';
update public.places set details = '{"teaser":"A bronze helmsman steering into the Atlantic wind.","facts":[{"text":"Américo Gomes sculpted it in 1934; it was unveiled here on the seafront in 1938, in tribute to sailors.","source":"https://www.culturacentro.gov.pt/media/14182/17_folhetosdigitaissiteesculturasmjm.pdf","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-homem-do-leme';
update public.places set details = '{"teaser":"The “English beach”, a sheltered cove in Foz.","facts":[{"text":"It was a favourite of the British in the 19th century, hence the name. The English also brought the fashion for seafront strolls.","source":"https://www.e-konomista.pt/ingleses-em-portugal-roteiro-pelo-porto/","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-ingleses';
update public.places set details = '{"teaser":"A fishing village where the washing still hangs out in the open.","facts":[{"text":"It sits near the mouth of the Douro and grew up as a fishing village.","source":"https://en.wikipedia.org/wiki/S%C3%A3o_Pedro_da_Afurada","needsReview":true},{"text":"Its communal washing tank and shared clotheslines are among the village’s must-sees.","source":"https://www.cm-gaia.pt/fotos/editor2/turismo/brochuras_desdobraveis/20250113_afurada.pdf","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-afurada';
update public.places set details = '{"teaser":"A family garden of roses and cacti, where a poet spent her childhood.","facts":[{"text":"The Andresen family bought the estate in 1895; Joana Andresen designed the J Letter Garden and the Rose Garden.","source":"https://en.wikipedia.org/wiki/Jardim_Bot%C3%A2nico_do_Porto","needsReview":true},{"text":"Two grandchildren grew up to be famous writers: the poet Sophia de Mello Breyner and Ruben A.","source":"https://en.wikipedia.org/wiki/Jardim_Bot%C3%A2nico_do_Porto","needsReview":true},{"text":"Look for the greenhouse of cacti and succulents, and the pond with waterlilies.","source":"https://en.wikipedia.org/wiki/Jardim_Bot%C3%A2nico_do_Porto","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-botanic';
update public.places set details = '{"teaser":"A Baroque palace with river balconies and statue-lined paths.","facts":[{"text":"Nicolau Nasoni built it in the mid-18th century for Canon Jerónimo de Távora.","source":"https://en.wikipedia.org/wiki/Pal%C3%A1cio_do_Freixo","needsReview":true},{"text":"The Marquis of Pombal had the Távora coats of arms destroyed after the plot against King Joseph.","source":"https://en.wikipedia.org/wiki/Pal%C3%A1cio_do_Freixo","needsReview":true},{"text":"Today it is a Pousada, a historic hotel.","source":"https://en.wikipedia.org/wiki/Pal%C3%A1cio_do_Freixo","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-freixo';
update public.places set details = '{"teaser":"A round monastery church high on the Gaia bank, facing the old city.","facts":[{"text":"Both its church and its cloister are perfectly circular. Building began in 1538 under King John III.","source":"https://en.wikipedia.org/wiki/Monastery_of_Serra_do_Pilar","needsReview":true},{"text":"On 12 May 1809, Wellesley (later Wellington) made his headquarters here before crossing the Douro to retake Porto.","source":"https://en.wikipedia.org/wiki/Second_Battle_of_Porto","needsReview":true},{"text":"A local barber showed his men a small boat hidden in the brush, and the crossing began.","source":"https://en.wikipedia.org/wiki/Second_Battle_of_Porto","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-serra-pilar';
update public.places set details = '{"teaser":"A Romantic-era house museum in the Crystal Palace gardens.","facts":[{"text":"The exiled King of Sardinia lived here briefly and died in Porto in 1849.","source":"https://en.wikipedia.org/wiki/Crystal_Palace_(Porto)","needsReview":true},{"text":"Today it is the Romantic Museum, showing how people lived in 19th-century Porto.","source":"https://en.wikipedia.org/wiki/Crystal_Palace_(Porto)","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-macieirinha';
update public.places set details = '{"teaser":"Photography in a former prison.","facts":[{"text":"The building was the Cadeia da Relação, Porto’s old prison next to the court of appeal.","source":"https://en.wikipedia.org/wiki/Portuguese_Centre_of_Photography","needsReview":true},{"text":"Architects Eduardo Souto de Moura and Humberto Vieira restored it; the centre moved in fully in 2001.","source":"https://en.wikipedia.org/wiki/Portuguese_Centre_of_Photography","needsReview":true},{"text":"Camilo Castelo Branco wrote his famous novel Doomed Love while jailed for his affair with Ana Plácido.","source":"https://en.wikipedia.org/wiki/Camilo_Castelo_Branco","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-cpf';
update public.places set details = '{"teaser":"Plain on the outside, a cave of gold inside.","facts":[{"text":"Building began in 1416 together with a convent for the Poor Clares; the church was finished in 1457.","source":"https://en.wikipedia.org/wiki/Igreja_de_Santa_Clara_(Porto)","needsReview":true},{"text":"Gilded Baroque woodcarving covers its vaults, walls, columns and arches.","source":"https://en.wikipedia.org/wiki/Gilded_woodcarving_in_Portugal","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-santa-clara';
update public.places set details = '{"teaser":"A whole chapel wrapped in blue-and-white tiles.","facts":[{"text":"15,947 tiles cover about 360 square metres of its walls.","source":"https://en.wikipedia.org/wiki/Chapel_of_Santa_Catarina","needsReview":true},{"text":"Eduardo Leite designed them; they went up in 1929. Before that, the walls were plain white.","source":"https://en.wikipedia.org/wiki/Chapel_of_Santa_Catarina","needsReview":true},{"text":"They tell the lives of Saint Francis of Assisi and Saint Catherine.","source":"https://en.wikipedia.org/wiki/Chapel_of_Santa_Catarina","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-almas';
update public.places set details = '{"teaser":"Two churches side by side, kept apart by a tiny house.","facts":[{"text":"A very narrow house was built between the Carmo and Carmelite churches so nuns and monks could have no contact.","source":"https://en.wikipedia.org/wiki/List_of_tourist_attractions_in_Porto","needsReview":true},{"text":"The two churches were classified together as a National Monument in 2013.","source":"https://en.wikipedia.org/wiki/List_of_tourist_attractions_in_Porto","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-carmo';
update public.places set details = '{"teaser":"A concert hall like a cut white gem.","facts":[{"text":"Rem Koolhaas’s OMA won the competition in 1999; the hall opened on 15 April 2005.","source":"https://en.wikipedia.org/wiki/Casa_da_M%C3%BAsica","needsReview":true},{"text":"It was launched as part of Porto’s year as European Capital of Culture in 2001.","source":"https://en.wikipedia.org/wiki/Casa_da_M%C3%BAsica","needsReview":true},{"text":"Look for the azulejo-tiled walls in the VIP hall.","source":"https://en.wikipedia.org/wiki/Casa_da_M%C3%BAsica","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-casa-musica';
update public.places set details = '{"teaser":"A grand theatre facing Batalha square.","facts":[{"text":"José Marques da Silva won the design competition; building started in 1911.","source":"https://en.wikipedia.org/wiki/S%C3%A3o_Jo%C3%A3o_National_Theatre","needsReview":true},{"text":"Four reliefs on the front show Kindness, Pain, Hatred and Love.","source":"https://en.wikipedia.org/wiki/S%C3%A3o_Jo%C3%A3o_National_Theatre","needsReview":true},{"text":"A Royal Theatre of São João stood here from 1794, until a fire in 1908.","source":"https://en.wikipedia.org/wiki/S%C3%A3o_Jo%C3%A3o_National_Theatre","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-tnsj';
update public.places set details = '{"teaser":"A rooftop arts club for gigs, club nights and exhibitions.","facts":[{"text":"It lives on the 4th floor of the Garage Building, an Art Deco building designed by Mário Abreu in 1939.","source":"https://www.maushabitos.com/en/sobre","needsReview":true},{"text":"Its name means “bad habits”. It sits right in front of the Coliseu do Porto.","source":"https://www.timeout.com/porto/art/maus-habitos","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-maus-habitos';
update public.places set details = '{"teaser":"Porto’s Art Deco municipal theatre.","facts":[{"text":"Architect and engineer Júlio Brito remade it in the Art Deco style.","source":"https://en.wikipedia.org/wiki/Rivoli_Theatre_(Portugal)","needsReview":true},{"text":"It is now the Teatro Municipal do Porto, the city’s own theatre.","source":"https://en.wikipedia.org/wiki/Rivoli_Theatre_(Portugal)","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-rivoli';
update public.places set details = '{"teaser":"A guitar maker’s shop where fado fills the room at night.","facts":[{"text":"It specialises in the plucked strings of Portuguese music: the guitarra, the viola Braguesa and the viola Campaniça.","source":"https://iporto.amp.pt/en/equipamentos/casa-da-guitarra/","needsReview":true},{"text":"Daily fado concerts sit alongside a permanent exhibition of Portuguese string instruments.","source":"https://iporto.amp.pt/en/equipamentos/casa-da-guitarra/","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-casa-guitarra';
update public.places set details = '{"teaser":"Eiffel’s iron railway arch leaping over the Douro.","facts":[{"text":"Gustave Eiffel’s company built it; King Luís I and Queen Maria Pia opened it on 4 November 1877.","source":"https://en.wikipedia.org/wiki/Maria_Pia_Bridge","needsReview":true},{"text":"The river was too fast and deep for piers, so one 160-metre arch crosses it: the world’s longest single arch at the time.","source":"https://en.wikipedia.org/wiki/Maria_Pia_Bridge","needsReview":true},{"text":"Trains moved to the new São João Bridge in 1991.","source":"https://en.wikipedia.org/wiki/Maria_Pia_Bridge","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-maria-pia';
update public.places set details = '{"teaser":"Old trams parked inside an old power station.","facts":[{"text":"It opened in May 1992 in the Massarelos power station that once fed Porto’s trams.","source":"https://en.wikipedia.org/wiki/Porto_Tram_Museum","needsReview":true},{"text":"Its collection has 16 electric cars, 5 trailers and two maintenance vehicles.","source":"https://en.wikipedia.org/wiki/Porto_Tram_Museum","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-tram-museum';
update public.places set details = '{"teaser":"A short gondola ride over the port wine lodges.","facts":[{"text":"The line is about 562 metres long, on 3 pylons, and opened in 2011.","source":"https://en.wikipedia.org/wiki/Gaia_Cable_Car","needsReview":true},{"text":"It runs from the riverside at Cais de Gaia up to Jardim do Morro, by the top of the Dom Luís I Bridge.","source":"https://en.wikipedia.org/wiki/Gaia_Cable_Car","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-gaia-cable-car';
update public.places set details = '{"teaser":"A Belle Époque café of mirrors, leather and carved wood.","facts":[{"text":"It began as an exclusive café where Porto’s high society met.","source":"https://en.wikipedia.org/wiki/Caf%C3%A9_Majestic","needsReview":true},{"text":"After years of decline it was listed in 1983, restored, and reopened in July 1994.","source":"https://en.wikipedia.org/wiki/Caf%C3%A9_Majestic","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-majestic';
update public.places set details = '{"teaser":"A local favourite for the francesinha, Porto’s gloriously messy sandwich.","facts":[{"text":"The francesinha is credited to Daniel David de Silva, who tried to adapt the croque monsieur for Portuguese tastes.","source":"https://en.wikipedia.org/wiki/Francesinha","needsReview":true},{"text":"He served it first in 1953 at A Regaleira, on Rua do Bonjardim. Steak, sausage, ham, cheese and a beer sauce. Bom apetite!","source":"https://en.wikipedia.org/wiki/Francesinha","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-santiago';
update public.places set details = '{"teaser":"A port wine lodge with a view across the river to Ribeira.","facts":[{"text":"In 1820 John Graham took 27 pipes of port instead of a debt: the first port ever shipped to Glasgow.","source":"https://en.wikipedia.org/wiki/Graham''s","needsReview":true},{"text":"The Symington family bought Graham’s in 1970.","source":"https://en.wikipedia.org/wiki/Graham''s","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-grahams';
update public.places set details = '{"teaser":"A long, steep stair from the cathedral down to the river.","facts":[{"text":"More than 400 steps link the Sé, Porto’s cathedral, with Ribeira. Good leg day!","source":"https://portosecreto.co/escadas-do-codecal/","needsReview":true},{"text":"Nobody knows for sure where the name comes from: maybe a word for hideout, maybe the codesso shrub.","source":"https://portosecreto.co/escadas-do-codecal/","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-codecal';
update public.places set details = '{"teaser":"Porto’s liveliest night-time street, where every other door is a bar.","facts":[{"text":"It opened in the 20th century, meant to be a pedestrian street under a glass roof like those in Paris.","source":"https://www.timeout.com/porto/things-to-do/the-most-beautiful-buildings-in-porto","needsReview":true},{"text":"It was half-forgotten for years, until the first bar opened in the mid-2000s and the rest followed.","source":"https://www.timeout.com/porto/things-to-do/the-most-beautiful-buildings-in-porto","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-galerias-paris';
update public.places set details = '{"teaser":"A scruffy little lookout with one of the best views in town.","facts":[{"text":"From here you see much of downtown and Ribeira, with the Dom Luís I Bridge and Gaia behind.","source":"https://www.portugalthings.com/best-viewpoints-porto/","needsReview":true},{"text":"It sits on private land, but access is allowed and free.","source":"https://www.portugalthings.com/best-viewpoints-porto/","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-vitoria';
update public.places set details = '{"teaser":"Porto’s grand old market, busy again after a long restoration.","facts":[{"text":"The market’s origins go back to 1838.","source":"https://www.theportugalnews.com/news/2022-09-15/renovated-bolhao-market-reopens-doors/70323","needsReview":true},{"text":"It reopened in September 2022, two years late, with 81 stalls, 38 shops and 10 restaurants.","source":"https://www.theportugalnews.com/news/2022-09-15/renovated-bolhao-market-reopens-doors/70323","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-bolhao';
update public.places set details = '{"teaser":"A cliffside lookout where Porto parties on São João night.","facts":[{"text":"On 23 June the party runs from the afternoon to the next morning, with sardines, caldo verde and soft plastic hammers.","source":"https://en.wikipedia.org/wiki/Festa_de_S%C3%A3o_Jo%C3%A3o_do_Porto","needsReview":true},{"text":"This lookout, beside the Infante Bridge, is a favourite spot for the midnight fireworks.","source":"https://visitporto.travel/en-GB/poi/5cd04b4ef979e00001fe47dc","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-fontainhas';
update public.places set details = '{"teaser":"An old riverside quarter of arcades and washing lines.","facts":[{"text":"Its landmarks include the Santo António Hospital and a stretch of the medieval city walls.","source":"https://en.wikipedia.org/wiki/Miragaia","needsReview":true},{"text":"The customs house built over its beach in the mid-1800s changed the waterfront completely.","source":"https://en.wikipedia.org/wiki/Miragaia","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-miragaia';
update public.places set details = '{"teaser":"A cemetery of grand family tombs and mourning statues.","facts":[{"text":"It was opened in a hurry after a cholera outbreak, when the existing cemeteries proved unsuitable.","source":"https://en.wikipedia.org/wiki/Agramonte_Cemetery","needsReview":true},{"text":"From the 1870s rich families built grand mausoleums, some with sculptures by Soares dos Reis and Teixeira Lopes.","source":"https://www.lonelyplanet.com/points-of-interest/cemiterio-de-agramonte/1509481","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-agramonte';
update public.places set details = '{"teaser":"A tiny, sturdy Romanesque church hiding behind its modern namesake.","facts":[{"text":"The oldest document about it dates from 1087, when it was consecrated.","source":"https://en.wikipedia.org/wiki/Church_of_S%C3%A3o_Martinho_de_Cedofeita","needsReview":true},{"text":"Its doorway has three round arches carved with animals and birds.","source":"https://en.wikipedia.org/wiki/Church_of_S%C3%A3o_Martinho_de_Cedofeita","needsReview":true},{"text":"Inside, two capitals survive from an even older 10th-century church.","source":"https://en.wikipedia.org/wiki/Church_of_S%C3%A3o_Martinho_de_Cedofeita","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-cedofeita';
update public.places set details = '{"teaser":"A six-sided white chapel on a rock in the surf.","facts":[{"text":"Its hexagonal plan is very unusual in Portuguese churches. At high tide the sea can surround it.","source":"https://postal.pt/nacional/nem-algarve-nem-lisboa-espanhois-dizem-que-esta-capela-que-fica-a-norte-e-dos-lugares-mais-incriveis-de-portugal/","needsReview":true},{"text":"Tradition says the rock was a place of worship even before the chapel was built.","source":"https://postal.pt/nacional/nem-algarve-nem-lisboa-espanhois-dizem-que-esta-capela-que-fica-a-norte-e-dos-lugares-mais-incriveis-de-portugal/","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-senhor-da-pedra';
update public.places set details = '{"teaser":"A huge white concrete arch over the mouth of the Douro.","facts":[{"text":"Edgar Cardoso designed it; it opened on 22 June 1963.","source":"https://en.wikipedia.org/wiki/Arr%C3%A1bida_Bridge","needsReview":true},{"text":"Its 270-metre main span was the largest concrete arch in the world at the time.","source":"https://en.wikipedia.org/wiki/Arr%C3%A1bida_Bridge","needsReview":true},{"text":"The deck rides up to 70 metres above the river.","source":"https://en.wikipedia.org/wiki/Arr%C3%A1bida_Bridge","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'porto-arrabida';
update public.places set details = '{"teaser":"A quiet Alentejo reservoir, rich in birdlife.","facts":[{"text":"It lies about 20 km north of Évora, little visited but rich in birds: herons, waders, birds of prey and larks.","source":"https://birdingplaces.eu/birdingplaces/portugal/albufeira-do-divor","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-divor';
update public.places set details = '{"teaser":"The lake that keeps Évora’s taps running.","facts":[{"text":"The dam, about 30 metres high, was finished in 1982 on the Degebe river.","source":"https://cnpgb.apambiente.pt/gr_barragens/gbingles/FichasIng/MonteNovofichaIng.htm","needsReview":true},{"text":"Its reservoir holds about 15.3 million cubic metres of water for the city and for farming.","source":"https://cnpgb.apambiente.pt/gr_barragens/gbingles/FichasIng/MonteNovofichaIng.htm","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-monte-novo';
update public.places set details = '{"teaser":"A Renaissance fountain topped with a marble globe.","facts":[{"text":"It was built in 1556; Cardinal Henrique called it one of the finest things in the city.","source":"https://www.cm-evora.pt/en/locais/largo-da-porta-de-moura/","needsReview":true},{"text":"Its sphere may reflect the conquests of Portugal’s empire.","source":"https://www.cm-evora.pt/en/locais/largo-da-porta-de-moura/","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-portas-moura-fountain';
update public.places set details = '{"teaser":"The marble fountain at the heart of Évora’s main square.","facts":[{"text":"The Henriquina fountain dates from 1570. Its eight jets stand for the eight streets that meet here.","source":"https://en.wikipedia.org/wiki/%C3%89vora","needsReview":true},{"text":"This square also saw many autos-da-fé during the Inquisition.","source":"https://en.wikipedia.org/wiki/%C3%89vora","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-giraldo-fountain';
update public.places set details = '{"teaser":"A Renaissance convent church in the countryside south of the city.","facts":[{"text":"Cardinal Henrique founded the convent in 1540.","source":"https://arqm.cm-evora.pt/pt-afcme-edn-3343","needsReview":true},{"text":"Diogo de Torralva is credited with designing the church in 1544, though scholars debate who drew it.","source":"https://www.infopedia.pt/artigos/$diogo-de-torralva","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-valverde';
update public.places set details = '{"teaser":"A Romantic garden of fake ruins, labyrinths and peacocks.","facts":[{"text":"Work began in 1863 under the Italian Giuseppe Cinatti, an architect and stage designer.","source":"https://www.cm-evora.pt/wp-content/uploads/2020/07/Poster-Jardim.pdf","needsReview":true},{"text":"He laid it out like stage sets; the “false ruins” are the best example. Peacocks often strut across them.","source":"https://www.cm-evora.pt/wp-content/uploads/2020/07/Poster-Jardim.pdf","needsReview":true},{"text":"Next to them stands the Galeria das Damas, part of King Manuel’s old palace.","source":"https://www.cm-evora.pt/wp-content/uploads/2020/07/Poster-Jardim.pdf","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-jardim-publico';
update public.places set details = '{"teaser":"Windmills on a granite hill with Évora spread out below.","facts":[{"text":"People lived on this granite hill in the Neolithic and Copper Ages.","source":"https://www.visitalentejo.pt/en/alentejo/nature/transalentejo/evora/","needsReview":true},{"text":"Quarries on its slopes supplied stone to build Évora, probably from Roman times.","source":"https://www.visitalentejo.pt/en/alentejo/nature/transalentejo/evora/","needsReview":true},{"text":"Four windmills stand here, from ruins to fully restored; one is a small museum.","source":"https://www.visitalentejo.pt/en/alentejo/nature/transalentejo/evora/","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-alto-sao-bento';
update public.places set details = '{"teaser":"An old railway line turned into a path through the cork oaks.","facts":[{"text":"It follows the old Ramal de Mora railway, which ran 60 km from Évora to Mora.","source":"https://en.wikipedia.org/wiki/Ramal_de_Mora","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-ecopista';
update public.places set details = '{"teaser":"Cork and holm oak country, the classic Alentejo montado.","facts":[{"text":"The University of Évora runs research on the montado here, at its Mitra campus.","source":"https://www.med.uevora.pt/?p=39568","needsReview":true},{"text":"The montado is a farmed savanna of cork and holm oaks, covering most of the Alentejo.","source":"https://www.med.uevora.pt/?p=39568","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-mitra';
update public.places set details = '{"teaser":"Roman columns standing in the middle of the old town.","facts":[{"text":"It was most likely built in the 1st century, for the cult of Emperor Augustus.","source":"https://en.wikipedia.org/wiki/Roman_Temple_of_%C3%89vora","needsReview":true},{"text":"It was used as a butcher’s shop from the 14th century until 1836, which helped it survive.","source":"https://en.wikipedia.org/wiki/Roman_Temple_of_%C3%89vora","needsReview":true},{"text":"The “Temple of Diana” name comes from a 17th-century legend, not from archaeology.","source":"https://en.wikipedia.org/wiki/Roman_Temple_of_%C3%89vora","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-roman-temple';
update public.places set details = '{"teaser":"Nearly a hundred standing stones on a hillside of cork oaks.","facts":[{"text":"Its first stones go back to the 6th millennium BC.","source":"https://en.wikipedia.org/wiki/Almendres_Cromlech","needsReview":true},{"text":"Nearly 100 menhirs stand in two oval rings: the largest group of its kind in Iberia.","source":"https://en.wikipedia.org/wiki/Almendres_Cromlech","needsReview":true},{"text":"Henrique Leonor Pina rediscovered it in 1966 while mapping the area’s geology.","source":"https://en.wikipedia.org/wiki/Almendres_Cromlech","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-almendres';
update public.places set details = '{"teaser":"A giant stone tomb, one of the biggest in Iberia.","facts":[{"text":"Its chamber is ringed by seven pillars about 8 metres high, reached by a 12-metre corridor.","source":"https://en.wikipedia.org/wiki/Great_Dolmen_of_Zambujeiro","needsReview":true},{"text":"The roof slab, about 7 metres across, has broken and now rests on the burial mound.","source":"https://en.wikipedia.org/wiki/Great_Dolmen_of_Zambujeiro","needsReview":true},{"text":"It has been a national monument since 1971.","source":"https://en.wikipedia.org/wiki/Great_Dolmen_of_Zambujeiro","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-zambujeiro';
update public.places set details = '{"teaser":"The graceful gallery that is all that remains of a royal palace.","facts":[{"text":"Some chroniclers say Vasco da Gama was given command of his India fleet here, in 1497.","source":"https://en.wikipedia.org/wiki/Royal_Palace_of_%C3%89vora","needsReview":true},{"text":"The Gallery of Dames is the only part of the palace still standing.","source":"https://en.wikipedia.org/wiki/Royal_Palace_of_%C3%89vora","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-dom-manuel';
update public.places set details = '{"teaser":"A Renaissance aqueduct striding into town, with homes between its arches.","facts":[{"text":"King John III ordered it in 1531–1532; the royal architect Francisco de Arruda directed the work.","source":"https://en.wikipedia.org/wiki/%C3%81gua_de_Prata_Aqueduct","needsReview":true},{"text":"It carries water about 18 km from springs near Divor.","source":"https://en.wikipedia.org/wiki/%C3%81gua_de_Prata_Aqueduct","needsReview":true},{"text":"Houses, shops and cafés were built between its arches, around Rua do Cano.","source":"https://en.wikipedia.org/wiki/%C3%81gua_de_Prata_Aqueduct","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-aqueduct';
update public.places set details = '{"teaser":"A fortress-like Gothic cathedral with towers of different spires.","facts":[{"text":"It is the largest medieval cathedral in Portugal.","source":"https://en.wikipedia.org/wiki/Cathedral_of_%C3%89vora","needsReview":true},{"text":"The first building went up from 1186; the Gothic cloister followed between 1317 and 1340.","source":"https://en.wikipedia.org/wiki/Cathedral_of_%C3%89vora","needsReview":true},{"text":"Its two towers have different spires, one covered in medieval coloured tiles.","source":"https://en.wikipedia.org/wiki/Cathedral_of_%C3%89vora","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-se';
update public.places set details = '{"teaser":"Vineyards around a monastery where silent monks lived.","facts":[{"text":"The winery is named after the Carthusian monastery (cartuxa) right next to it.","source":"https://farehamwinecellar.co.uk/Products/wine/red/cartuxa-colheita-tinto-evora/","needsReview":true},{"text":"It belongs to the Eugénio de Almeida Foundation, set up in 1963 to support social and cultural life in the region.","source":"https://farehamwinecellar.co.uk/Products/wine/red/cartuxa-colheita-tinto-evora/","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-cartuxa';
update public.places set details = '{"teaser":"A Jesuit college whose classrooms are lined with tiles.","facts":[{"text":"Cardinal Henry founded it in 1559, Portugal’s second university, and gave it to the Jesuits to run.","source":"https://en.wikipedia.org/wiki/University_of_%C3%89vora","needsReview":true},{"text":"Cavalry surrounded it on 8 February 1759, when Pombal expelled the Jesuits. It reopened only in 1973.","source":"https://en.wikipedia.org/wiki/University_of_%C3%89vora","needsReview":true},{"text":"The classroom tiles show scenes like “Aristotle teaching Alexander the Great”.","source":"https://en.wikipedia.org/wiki/University_of_%C3%89vora","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-university';
update public.places set details = '{"teaser":"Évora’s treasure chest of paintings, sculpture and Roman finds.","facts":[{"text":"Founded in 1915, it holds more than 20,000 pieces.","source":"https://en.wikipedia.org/wiki/Frei_Manuel_do_Cen%C3%A1culo_National_Museum","needsReview":true},{"text":"It is named after Frei Manuel do Cenáculo, an archbishop who opened his collection to the public.","source":"https://en.wikipedia.org/wiki/Frei_Manuel_do_Cen%C3%A1culo_National_Museum","needsReview":true},{"text":"Look for the 13-panel altarpiece from the cathedral’s old high altar.","source":"https://en.wikipedia.org/wiki/Frei_Manuel_do_Cen%C3%A1culo_National_Museum","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-museu-evora';
update public.places set details = '{"teaser":"Alentejo crafts, from cork to clay, side by side with modern design.","facts":[{"text":"It opened in November 2011, built around the Paulo Parra collection of traditional Alentejo crafts.","source":"https://lifecooler.com/artigo/comer/made-museu-de-artesanato-e-design-de-vora/404527","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-artesanato';
update public.places set details = '{"teaser":"A historic public library founded by a book-loving archbishop.","facts":[{"text":"Archbishop Frei Manuel do Cenáculo founded it in 1805, giving his own books and collections.","source":"https://www.redalyc.org/pdf/635/63524088003.pdf","needsReview":true},{"text":"French troops looted it in 1808 and destroyed much of the collection.","source":"https://www.redalyc.org/pdf/635/63524088003.pdf","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-biblioteca';
update public.places set details = '{"teaser":"Contemporary art in the old palace of the Inquisition.","facts":[{"text":"The palace was the first in Portugal built to house the Inquisition, in 1536.","source":"https://lifecooler.com/artigo/dormir/palcio-da-inquisio/325586","needsReview":true},{"text":"Its Casas Pintadas hold a rare example of mid-16th-century palace wall painting.","source":"https://www.cm-evora.pt/en/locais/centro-de-arte-e-cultura/","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-fea';
update public.places set details = '{"teaser":"A little chapel dressed up as a castle.","facts":[{"text":"It dates from about 1480, built on the grounds of a small leper hospital.","source":"https://www.lonelyplanet.com/portugal/central-portugal/evora/attractions/ermida-de-sao-bras/a/poi-sig/1541202/360364","needsReview":true},{"text":"Crenellations and round towers with conical tops make it look like a fortress.","source":"https://www.infopedia.pt/artigos/$ermida-de-s.-bras-(evora)","needsReview":true},{"text":"Artillery fire badly damaged it during the Restoration wars in 1663.","source":"https://www.infopedia.pt/artigos/$ermida-de-s.-bras-(evora)","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-sao-bras';
update public.places set details = '{"teaser":"A railway station decorated with tile pictures of the Alentejo.","facts":[{"text":"A long row of tile murals shows Évora’s buildings and the countryside: donkeys and old windmills.","source":"https://www.komoot.com/highlight/6570057","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-station-tiles';
update public.places set details = '{"teaser":"A convent church lined with 17th-century tiles.","facts":[{"text":"The convent was founded between 1452 and 1459; its church and Renaissance cloister survive.","source":"https://www.infopedia.pt/artigos/$mosteiro-de-santa-clara-(evora)","needsReview":true},{"text":"Inside, patterned 17th-century azulejos line the single nave.","source":"https://www.infopedia.pt/artigos/$mosteiro-de-santa-clara-(evora)","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-santa-clara';
update public.places set details = '{"teaser":"A small church with a tiled corner under its choir.","facts":[{"text":"A tile panel under the choir shows scenes from the life of the Virgin Mary.","source":"https://arqm.cm-evora.pt/index.php/pt-afcme-dft-68-4346","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-merces';
update public.places set details = '{"teaser":"A jewel-box theatre with an Italian-style auditorium.","facts":[{"text":"It opened on 1 June 1892, after its promoter died during construction.","source":"https://www.geocaching.com/geocache/GC9ZF50","needsReview":true},{"text":"It is part of the European Route of Historic Theatres.","source":"https://www.cm-evora.pt/?p=36498","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-garcia-resende';
update public.places set details = '{"teaser":"Eleven days of rides, music and food stalls every June.","facts":[{"text":"The first fair was held on 24 June 1569, under a royal charter from King Sebastião.","source":"https://www.theportugalnews.com/news/2025-06-18/centuries-old-fair-returns/98715","needsReview":true},{"text":"It takes over the Rossio de São Brás, outside the old walls; the tasquinhas (food stalls) are a must.","source":"https://www.theportugalnews.com/news/2025-06-18/centuries-old-fair-returns/98715","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-sao-joao-fair';
update public.places set details = '{"teaser":"An old bullring that now hosts concerts and fairs.","facts":[{"text":"It opened on 19 May 1889, with King Luís and his court there.","source":"https://www.cm-evora.pt/en/locais/arena-devora/","needsReview":true},{"text":"It held about 5,000 people; in 2007 it reopened as a multipurpose hall, the Arena d’Évora.","source":"https://www.cm-evora.pt/en/locais/arena-devora/","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-arena';
update public.places set details = '{"teaser":"A 19th-century society for music, balls and theatre on the main square.","facts":[{"text":"It was founded in 1849, after the fighting between liberals and absolutists; its name stands for harmony between people.","source":"https://arqm.cm-evora.pt/index.php/sociedade-harmonia-eborense-2","needsReview":true},{"text":"Music, balls, plays and lectures were part of its life from the start.","source":"https://www.rdpc.uevora.pt/rdpc/handle/10174/27893","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-harmonia';
update public.places set details = '{"teaser":"A small auditorium in the historic centre.","facts":[{"text":"It seats just over 50 people and hosted alternative cinema sessions for years.","source":"https://www.rtp.pt/noticias/cultura/cinema-alternativo-suspenso-em-evora-por-falta-de-condicoes-do-espaco_n1723777","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-soror-mariana';
update public.places set details = '{"teaser":"A chapel whose walls are built from human bones.","facts":[{"text":"Franciscan friars lined it with the bones of an estimated 5,000 people from the city’s old cemeteries.","source":"https://en.wikipedia.org/wiki/Capela_dos_Ossos","needsReview":true},{"text":"The words over the door read: “We bones, lying here bare, await yours.”","source":"https://en.wikipedia.org/wiki/Capela_dos_Ossos","needsReview":true},{"text":"It is a small chapel beside the entrance of the Church of St Francis.","source":"https://en.wikipedia.org/wiki/Capela_dos_Ossos","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-bones';
update public.places set details = '{"teaser":"Évora’s market hall of cheese, sausages and Saturday farmers.","facts":[{"text":"The market moved here to Praça 1º de Maio in 1880, into a wrought-iron hall.","source":"https://wetravelportugal.com/evora-portugal/","needsReview":true},{"text":"On Saturdays, farmers gather outside to sell their produce.","source":"https://wetravelportugal.com/evora-portugal/","needsReview":true},{"text":"Queijo de Évora is a protected (PDO) cheese.","source":"https://en.wikipedia.org/wiki/List_of_Portuguese_food_and_drink_products_with_protected_status","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-mercado';
update public.places set details = '{"teaser":"A lane where homes are tucked under the arches of the aqueduct.","facts":[{"text":"Houses, shops and cafés were built between the aqueduct’s arches here.","source":"https://en.wikipedia.org/wiki/%C3%81gua_de_Prata_Aqueduct","needsReview":true},{"text":"The arches shrink as the ground rises, until the aqueduct disappears underground.","source":"https://ourworldforyou.com/9-reasons-to-visit-evora-in-portugal/","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-rua-do-cano';
update public.places set details = '{"teaser":"Convent sweets made to the nuns’ old recipes.","facts":[{"text":"Pão de rala comes from the Convent of Santa Helena do Monte Calvário in Évora.","source":"https://www.portugalthings.com/best-sweets-alentejo","needsReview":true},{"text":"It is made with sugar, almonds and egg yolks, and filled with sweet gila squash. Delicioso!","source":"https://www.portugalthings.com/best-sweets-alentejo","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-pao-de-rala';
update public.places set details = '{"teaser":"A lone standing stone among the cork oaks.","facts":[{"text":"It is a single stone about 4 metres high, with faint carvings near the top.","source":"https://www.lonelyplanet.com/pois/1531009","needsReview":true},{"text":"It stands about two and a half kilometres before the Almendres Cromlech.","source":"https://www.lonelyplanet.com/pois/1531009","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-menhir';
update public.places set details = '{"teaser":"A hidden courtyard on the hilltop where Évora’s castle once stood.","facts":[{"text":"The Counts of Basto palace here stands where a Moorish fortress once stood.","source":"https://www.ancient-history-sites.com/?p=121975","needsReview":true},{"text":"King Ferdinand I stayed here on his visits to Évora; John I later gave it to Nuno Álvares Pereira.","source":"https://www.ancient-history-sites.com/?p=121975","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-sao-miguel';
update public.places set details = '{"teaser":"A five-sided tower from the old city walls.","facts":[{"text":"It is a pentagonal medieval tower, part of the Palace of the Dukes of Cadaval.","source":"https://whichmuseum.com/museum/cadaval-palace-evora-46863","needsReview":true},{"text":"It has been a National Monument since 1920.","source":"https://whichmuseum.com/museum/cadaval-palace-evora-46863","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-cinco-quinas';
update public.places set details = '{"teaser":"A tiny tavern where the kitchen decides what you eat.","facts":[{"text":"There is no menu: you trust the house and go with the flow.","source":"https://saltofportugal.com/2016/02/29/a-tavern-called-wednesday/","needsReview":true},{"text":"Its name comes from the owner’s home village in Beira Alta, called Quarta Feira (Wednesday).","source":"https://saltofportugal.com/2016/02/29/a-tavern-called-wednesday/","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-quarta-feira';
update public.places set details = '{"teaser":"A Carthusian monastery where monks kept silence for centuries.","facts":[{"text":"Archbishop Teotónio de Bragança had it built for Carthusian monks between 1587 and 1598.","source":"https://www.fea.pt/fileadmin/user_upload/BROCHURA_saudades.pdf","needsReview":true},{"text":"Its bells have marked the hours of prayer since 1598.","source":"https://www.fea.pt/fileadmin/user_upload/BROCHURA_saudades.pdf","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-scala-coeli';
update public.places set details = '{"teaser":"Quiet lanes of the city’s old Jewish quarter.","facts":[{"text":"Évora was home to one of Portugal’s important Jewish communities in the 15th century.","source":"https://en.wikipedia.org/wiki/History_of_the_Jews_in_Portugal","needsReview":true},{"text":"In 1496 King Manuel I ordered Jews to leave; in 1497 this became forced conversion.","source":"https://en.wikipedia.org/wiki/History_of_the_Jews_in_Portugal","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-judiaria';
update public.places set details = '{"teaser":"A Roman city gate still in daily use.","facts":[{"text":"It was built in the late 2nd or early 3rd century, when Évora was Ebora Liberalitas Julia.","source":"https://www.ancient-history-sites.com/sites/roman-arch-of-dona-isabel/","needsReview":true},{"text":"Its granite blocks were laid without mortar.","source":"https://www.ancient-history-sites.com/sites/roman-arch-of-dona-isabel/","needsReview":true},{"text":"It is named after Queen Isabel, wife of King Denis I.","source":"https://www.ancient-history-sites.com/sites/roman-arch-of-dona-isabel/","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-arco-isabel';
update public.places set details = '{"teaser":"A church front guarded by four stone giants.","facts":[{"text":"Work on the convent began in 1524; it is called the city’s first Renaissance monument.","source":"https://www.geocaching.com/geocache/GC6XBFR","needsReview":true},{"text":"Above each group of giants is a stone sphere with a flame.","source":"https://www.frommers.com/destinations/evora/attractions/igreja-de-nossa-senhora-de-graa","needsReview":true},{"text":"For centuries locals have called the giants the “Meninos da Graça”, the Graça boys.","source":"https://expatinportugal.substack.com/p/the-stuff-of-legend","needsReview":true}]}'::jsonb where source = 'seed' and source_id = 'evora-graca';

